/* Fakt des Tages: was an diesem Kalendertag passiert ist oder heute gefeiert wird (ohne Politik und Geschichte) */
const DAY_FACTS = {
  "01-01": { y: 1801, e: "🪐", t: "Ceres wird entdeckt", x: "In der Neujahrsnacht 1801 entdeckte der Astronom Giuseppe Piazzi in Palermo ein Lichtpünktchen zwischen Mars und Jupiter: Ceres. Als man es aus den Augen verlor, berechnete der junge Carl Friedrich Gauß die Bahn so genau, dass es wiedergefunden wurde. Heute gilt Ceres als Zwergplanet im Asteroidengürtel." },
  "01-02": { y: 1959, e: "🚀", t: "Luna 1 fliegt zum Mond", x: "Die sowjetische Sonde Luna 1 startete an diesem Tag als erstes Raumfahrzeug, das der Anziehung der Erde entkam. Eigentlich sollte sie auf dem Mond einschlagen, verfehlte ihn aber um rund 6.000 Kilometer. Seitdem kreist sie als erster künstlicher Himmelskörper um die Sonne." },
  "01-03": { y: 2019, e: "🌑", t: "Landung auf der Rückseite des Mondes", x: "Die chinesische Sonde Chang’e 4 landete als erste überhaupt auf der erdabgewandten Seite des Mondes. Weil von dort kein direkter Funkkontakt zur Erde möglich ist, wurden die Signale über einen eigens gestarteten Relaissatelliten übertragen. Mit an Bord: ein kleiner Rover und Pflanzensamen für ein Experiment." },
  "01-04": { e: "✋", t: "Welt-Braille-Tag", x: "Heute vor über 200 Jahren, am 4. Januar 1809, wurde Louis Braille in Frankreich geboren. Er erblindete als Kind und entwickelte mit nur 15 Jahren eine Schrift aus erhabenen Punkten, die man mit den Fingern ertasten kann. Seine Punktschrift wird bis heute weltweit von blinden Menschen genutzt." },
  "01-05": { y: 2005, e: "🔭", t: "Eris wird entdeckt", x: "Auf Aufnahmen eines Teleskops in Kalifornien entdeckten Astronomen einen fernen Himmelskörper jenseits von Neptun, der fast so groß ist wie Pluto: Eris. Der Fund löste eine Debatte aus, was ein Planet eigentlich ist – und führte dazu, dass Pluto im Jahr darauf zum Zwergplaneten erklärt wurde." },
  "01-06": { y: 1912, e: "🌍", t: "Wandernde Kontinente", x: "Der Meteorologe Alfred Wegener stellte in Frankfurt erstmals seine Idee vor, dass die Kontinente einst einen einzigen Urkontinent bildeten und auseinandergedriftet sind. Die meisten Geologen lachten ihn aus. Erst Jahrzehnte nach seinem Tod bestätigte die Plattentektonik, dass er im Kern recht hatte." },
  "01-07": { y: 1610, e: "🔭", t: "Galilei sieht Jupitermonde", x: "Mit seinem selbst gebauten Fernrohr entdeckte Galileo Galilei neben Jupiter kleine Lichtpunkte, die ihre Position von Nacht zu Nacht änderten. Er erkannte: Es sind Monde, die um Jupiter kreisen. Damit war klar, dass sich nicht alles am Himmel um die Erde dreht." },
  "01-08": { y: 1942, e: "🌌", t: "Stephen Hawking wird geboren", x: "Der britische Physiker Stephen Hawking erforschte Schwarze Löcher und den Ursprung des Universums. Obwohl er wegen einer Nervenkrankheit fast vollständig gelähmt war und über einen Sprachcomputer kommunizierte, wurde sein Buch „Eine kurze Geschichte der Zeit“ zu einem Weltbestseller." },
  "01-09": { y: 2007, e: "📱", t: "Das iPhone wird vorgestellt", x: "Auf einer Konferenz in San Francisco präsentierte Steve Jobs ein Gerät, das Telefon, Musikspieler und Internetzugang vereinte – bedient mit den Fingern auf einem Bildschirm statt mit Tasten. Das iPhone machte Smartphones mit Touchscreen massentauglich und veränderte den Alltag von Milliarden Menschen." },
  "01-10": { y: 1863, e: "🚇", t: "Die erste U-Bahn der Welt", x: "In London fuhr die erste unterirdische Eisenbahn der Welt, die Metropolitan Railway. Die Züge wurden damals noch von Dampflokomotiven gezogen, was die Tunnel stark verrauchte. Trotzdem nutzten schon am ersten Tag Zehntausende Fahrgäste die neue Verbindung." },
  "01-11": { y: 1922, e: "💉", t: "Die erste Insulinspritze", x: "In Toronto erhielt der vierzehnjährige Leonard Thompson als erster Mensch eine Spritze mit Insulin. Er litt an Typ-1-Diabetes, damals ein Todesurteil. Nach einer verbesserten zweiten Gabe wenige Tage später erholte er sich. Seitdem können Millionen Menschen mit Diabetes leben." },
  "01-12": { y: 1628, e: "🐈", t: "Charles Perrault wird geboren", x: "Der Franzose Charles Perrault schrieb viele Märchen auf, die wir bis heute kennen, darunter Aschenputtel, Dornröschen, Rotkäppchen und Der gestiefelte Kater. Seine Sammlung erschien über hundert Jahre vor den Märchen der Brüder Grimm und beeinflusste diese stark." },
  "01-13": { y: 1910, e: "📻", t: "Oper im Radio", x: "Aus der Metropolitan Opera in New York wurde erstmals ein Konzert live per Funk übertragen, mit dem berühmten Tenor Enrico Caruso. Nur wenige Menschen mit Empfangsgeräten konnten zuhören, und der Klang war dürftig. Doch es war einer der ersten Schritte zum Rundfunk, wie wir ihn kennen." },
  "01-14": { y: 2005, e: "🪐", t: "Landung auf dem Saturnmond Titan", x: "Die europäische Sonde Huygens schwebte an Fallschirmen durch die dichte Atmosphäre des Saturnmonds Titan und landete auf seiner Oberfläche. Es war die bisher am weitesten von der Erde entfernte Landung. Die Bilder zeigten Flussläufe und Kiesel – geformt nicht von Wasser, sondern von flüssigem Methan." },
  "01-15": { y: 2001, e: "📚", t: "Wikipedia geht online", x: "Die freie Online-Enzyklopädie Wikipedia startete, an der jeder mitschreiben kann. Viele hielten die Idee für zum Scheitern verurteilt. Heute gibt es Wikipedia in über 300 Sprachen, und sie gehört zu den meistbesuchten Webseiten der Welt. Die deutsche Ausgabe entstand wenige Monate später." },
  "01-16": { y: 1932, e: "🦍", t: "Dian Fossey wird geboren", x: "Die amerikanische Zoologin Dian Fossey lebte fast zwei Jahrzehnte in den Bergwäldern Ruandas und erforschte Berggorillas. Sie zeigte, dass die Tiere friedliche, soziale Wesen sind, und kämpfte gegen Wilderer. Ihr Buch „Gorillas im Nebel“ wurde später verfilmt." },
  "01-17": { y: 1929, e: "🥫", t: "Popeye taucht auf", x: "In einem amerikanischen Zeitungscomic hatte der Seemann Popeye seinen ersten Auftritt. Später wurde er dafür berühmt, dass Spinat ihn stark macht. Die Legende, Spinat sei besonders eisenreich, beruht übrigens auf einem Irrtum – er enthält nicht mehr Eisen als viele andere Gemüse." },
  "01-18": { y: 1882, e: "🍯", t: "A. A. Milne wird geboren", x: "Der englische Schriftsteller Alan Alexander Milne erfand die Geschichten um den Bären Pu und seine Freunde. Vorbild waren die Stofftiere seines Sohnes Christopher Robin. Der Hundertsechzig-Morgen-Wald beruht auf einem echten Wald in Südengland, den man noch heute besuchen kann." },
  "01-19": { y: 1736, e: "⚙️", t: "James Watt wird geboren", x: "Der schottische Ingenieur James Watt verbesserte die Dampfmaschine entscheidend, indem er den Dampf in einem getrennten Behälter abkühlen ließ. Seine Maschinen verbrauchten viel weniger Kohle und trieben die Industrialisierung an. Nach ihm ist die Einheit der Leistung benannt: das Watt." },
  "01-20": { y: 1930, e: "👨‍🚀", t: "Buzz Aldrin wird geboren", x: "Der amerikanische Astronaut Buzz Aldrin betrat 1969 als zweiter Mensch den Mond, nur Minuten nach Neil Armstrong. Er war zudem ein ausgebildeter Ingenieur, der sich mit Andockmanövern im All beschäftigte. Viele der berühmtesten Mondfotos zeigen ihn, weil Armstrong meist die Kamera trug." },
  "01-21": { e: "🤗", t: "Weltknuddeltag", x: "Heute ist Weltknuddeltag. Umarmungen sind gut fürs Wohlbefinden: Bei angenehmem Körperkontakt schüttet der Körper das Hormon Oxytocin aus, das Vertrauen und Verbundenheit fördert und Stress dämpfen kann. Natürlich gilt: Nur umarmen, wer es auch möchte." },
  "01-22": { y: 1561, e: "🔬", t: "Francis Bacon wird geboren", x: "Der englische Philosoph Francis Bacon forderte, Wissen durch genaue Beobachtung und Experimente zu gewinnen, statt sich auf alte Autoritäten zu verlassen. Damit wurde er zu einem Wegbereiter der modernen Naturwissenschaft. Ihm wird der Satz zugeschrieben: Wissen ist Macht." },
  "01-23": { y: 1960, e: "🌊", t: "Am tiefsten Punkt der Meere", x: "Jacques Piccard und Don Walsh tauchten mit dem Tauchboot Trieste in den Marianengraben hinab, fast elf Kilometer tief. Nach fast fünf Stunden Abstieg erreichten sie den Grund. Am Boden sahen sie zu ihrer Überraschung Lebewesen – der Beweis, dass selbst dort Leben möglich ist." },
  "01-24": { y: 1984, e: "🖥️", t: "Der erste Macintosh", x: "Apple stellte den Macintosh vor, einen der ersten erschwinglichen Computer, den man mit einer Maus und Symbolen auf dem Bildschirm bediente statt mit getippten Befehlen. Diese grafische Oberfläche mit Fenstern und Papierkorb wurde später zum Standard für fast alle Computer." },
  "01-25": { y: 1924, e: "⛷️", t: "Die ersten Winterspiele", x: "Im französischen Chamonix begann eine internationale Wintersportwoche, die später als erste Olympische Winterspiele anerkannt wurde. Rund 250 Sportler aus 16 Ländern traten an, unter anderem im Eisschnelllauf, Eishockey und Skispringen. Frauen durften nur im Eiskunstlauf starten." },
  "01-26": { y: 1905, e: "💎", t: "Der größte Diamant", x: "In einer Mine in Südafrika fand ein Aufseher einen Rohdiamanten von über 600 Gramm – den größten jemals gefundenen Diamanten in Edelsteinqualität. Der Cullinan wurde in neun große und viele kleine Steine geschliffen. Die größten schmücken heute die britischen Kronjuwelen." },
  "01-27": { y: 1756, e: "🎹", t: "Mozart wird geboren", x: "In Salzburg kam Wolfgang Amadeus Mozart zur Welt. Schon als Kind trat er als Wunderkind an Europas Höfen auf und komponierte mit fünf Jahren erste Stücke. In nur 35 Lebensjahren schuf er über 600 Werke, darunter Die Zauberflöte und Eine kleine Nachtmusik." },
  "01-28": { y: 1813, e: "📖", t: "Stolz und Vorurteil erscheint", x: "Der Roman „Stolz und Vorurteil“ der englischen Schriftstellerin Jane Austen wurde veröffentlicht, zunächst ohne ihren Namen. Die Geschichte von Elizabeth Bennet und Mr. Darcy gehört bis heute zu den beliebtesten Liebesromanen der Welt und wurde unzählige Male verfilmt." },
  "01-29": { y: 1886, e: "🚗", t: "Das Auto wird patentiert", x: "Carl Benz meldete in Mannheim sein Fahrzeug mit Gasmotorenbetrieb zum Patent an: ein dreirädriger Wagen mit Benzinmotor. Die Patentschrift gilt als Geburtsurkunde des Automobils. Der Motorwagen erreichte rund 16 Kilometer pro Stunde – kaum schneller als ein Radfahrer." },
  "01-30": { y: 1969, e: "🎸", t: "Konzert auf dem Dach", x: "Die Beatles spielten überraschend auf dem Dach ihres Plattenstudios in London – ihr letzter öffentlicher Auftritt. Auf den Straßen blieben Menschen stehen und schauten nach oben, bis nach rund 40 Minuten die Polizei wegen Lärmbeschwerden kam. Der Auftritt wurde später legendär." },
  "01-31": { y: 1797, e: "🎼", t: "Franz Schubert wird geboren", x: "Der Wiener Komponist Franz Schubert schrieb über 600 Lieder, darunter Vertonungen von Goethe-Gedichten wie „Der Erlkönig“, den er als Teenager komponierte. Er wurde nur 31 Jahre alt. Zu Lebzeiten war er vor allem in Freundeskreisen bekannt, erst später weltberühmt." },
  "02-01": { y: 1884, e: "📕", t: "Das große Wörterbuch beginnt", x: "In England erschien der erste Teil des Oxford English Dictionary, das alle englischen Wörter mit ihrer Geschichte erfassen sollte. Geplant waren zehn Jahre Arbeit – fertig war das Werk erst 1928. Zu den fleißigsten freiwilligen Helfern gehörte ein Mann, der in einer psychiatrischen Klinik lebte." },
  "02-02": { e: "🦆", t: "Tag der Feuchtgebiete", x: "Heute ist Welttag der Feuchtgebiete. Moore, Sümpfe und Flussauen speichern viel Kohlenstoff, reinigen Wasser und schützen vor Hochwasser. Zugleich sind sie Lebensraum für unzählige Vögel und Amphibien. Weltweit ist ein großer Teil der Feuchtgebiete in den letzten Jahrhunderten trockengelegt worden." },
  "02-03": { y: 1809, e: "🎻", t: "Felix Mendelssohn wird geboren", x: "Der in Hamburg geborene Komponist Felix Mendelssohn Bartholdy schrieb schon mit 17 Jahren eine Ouvertüre zu Shakespeares „Sommernachtstraum“. Jahre später ergänzte er die Bühnenmusik um den Hochzeitsmarsch, der noch heute bei unzähligen Trauungen erklingt. Er sorgte außerdem dafür, dass die Musik von Bach wiederentdeckt wurde." },
  "02-04": { e: "🎗️", t: "Weltkrebstag", x: "Heute ist Weltkrebstag. Krebs entsteht, wenn Zellen unkontrolliert wachsen. Rund vier von zehn Krebsfällen gelten als vermeidbar, etwa durch Verzicht auf Rauchen, Sonnenschutz, Bewegung und Impfungen gegen bestimmte Viren. Dank früherer Erkennung und besserer Therapien überleben heute viel mehr Menschen eine Krebserkrankung als früher." },
  "02-05": { y: 1840, e: "🚲", t: "John Boyd Dunlop wird geboren", x: "Der schottische Tierarzt John Boyd Dunlop wollte seinem Sohn das Dreiradfahren auf holprigen Wegen angenehmer machen. Er baute einen mit Luft gefüllten Gummireifen. Seine Erfindung machte Fahrräder und später Autos viel bequemer – und sein Name steht bis heute auf Reifen." },
  "02-06": { y: 1971, e: "⛳", t: "Golf auf dem Mond", x: "Während der Mission Apollo 14 holte Astronaut Alan Shepard einen selbst gebauten Golfschläger hervor und schlug zwei Golfbälle über die Mondoberfläche. Wegen der geringen Schwerkraft flogen sie weit, auch wenn er im steifen Raumanzug nur einhändig schlagen konnte. Die Bälle liegen noch heute dort." },
  "02-07": { y: 1812, e: "🎄", t: "Charles Dickens wird geboren", x: "Der englische Schriftsteller Charles Dickens musste als Kind in einer Fabrik arbeiten. Diese Erfahrung prägte Romane wie „Oliver Twist“, in denen er Armut und Kinderarbeit anprangerte. Seine Geschichte „Eine Weihnachtsgeschichte“ über den geizigen Scrooge wird bis heute jedes Jahr neu erzählt." },
  "02-08": { y: 1828, e: "🎈", t: "Jules Verne wird geboren", x: "Der Franzose Jules Verne schrieb Abenteuerromane wie „20.000 Meilen unter dem Meer“ und „In 80 Tagen um die Welt“. Er beschrieb U-Boote, Mondreisen und Flugmaschinen lange bevor es sie gab. Viele spätere Forscher und Ingenieure nannten seine Bücher als Inspiration." },
  "02-09": { y: 1969, e: "✈️", t: "Der Jumbo hebt ab", x: "Die Boeing 747 absolvierte ihren Erstflug in der Nähe von Seattle. Mit ihrem charakteristischen Buckel war sie damals das größte Passagierflugzeug der Welt und machte Fernreisen für viel mehr Menschen erschwinglich. Wegen ihrer Größe bekam sie den Spitznamen Jumbo-Jet." },
  "02-10": { e: "🫘", t: "Tag der Hülsenfrüchte", x: "Heute ist der Welttag der Hülsenfrüchte. Linsen, Bohnen, Erbsen und Kichererbsen liefern viel Eiweiß und Ballaststoffe. Ihre Wurzeln leben mit Bakterien zusammen, die Stickstoff aus der Luft binden – so düngen die Pflanzen den Boden ganz ohne Kunstdünger." },
  "02-11": { y: 2016, e: "🌀", t: "Gravitationswellen nachgewiesen", x: "Forscher gaben bekannt, dass sie erstmals Gravitationswellen gemessen hatten: winzige Verzerrungen von Raum und Zeit, ausgelöst durch zwei verschmelzende Schwarze Löcher über eine Milliarde Lichtjahre entfernt. Albert Einstein hatte sie hundert Jahre zuvor vorhergesagt, aber für unmessbar klein gehalten." },
  "02-12": { y: 1809, e: "🐢", t: "Darwin-Tag", x: "Am 12. Februar 1809 wurde Charles Darwin geboren. Mit seiner Theorie der natürlichen Auslese erklärte er, wie sich Lebewesen über viele Generationen verändern und neue Arten entstehen. Weltweit wird sein Geburtstag als Darwin-Tag gefeiert, um die Wissenschaft zu würdigen." },
  "02-13": { e: "📻", t: "Welttag des Radios", x: "Heute ist Welttag des Radios. Auch im Zeitalter von Streaming und Smartphones erreicht das Radio weltweit mehr Menschen als fast jedes andere Medium. Besonders in Katastrophen ist es wichtig, weil ein batteriebetriebenes Gerät auch ohne Strom- und Mobilfunknetz Informationen empfängt." },
  "02-14": { y: 1990, e: "🔵", t: "Ein blassblauer Punkt", x: "Die Raumsonde Voyager 1 drehte sich aus rund sechs Milliarden Kilometern Entfernung noch einmal um und fotografierte die Erde. Auf dem Bild ist sie nur ein winziger, blassblauer Punkt in einem Sonnenstrahl. Der Astronom Carl Sagan hatte die Aufnahme angeregt, um zu zeigen, wie klein und kostbar unsere Welt ist." },
  "02-15": { y: 1564, e: "🔭", t: "Galileo Galilei wird geboren", x: "Der Italiener Galileo Galilei gilt als einer der Begründer der modernen Naturwissenschaft. Er untersuchte Pendel und fallende Körper, verbesserte das Fernrohr und entdeckte Jupitermonde, Mondkrater und Venusphasen. Er setzte auf Experimente und Messungen statt auf alte Lehrmeinungen." },
  "02-16": { y: 1834, e: "🪼", t: "Ernst Haeckel wird geboren", x: "Der Biologe Ernst Haeckel aus Potsdam erforschte winzige Meereslebewesen und zeichnete sie in prachtvollen Tafeln. Sein Werk „Kunstformen der Natur“ beeinflusste sogar Architekten und Künstler des Jugendstils. Er prägte außerdem das Wort Ökologie." },
  "02-17": { e: "🐈", t: "Tag der Katze", x: "In Deutschland und Italien wird heute der Tag der Katze gefeiert. Katzen sind die beliebtesten Haustiere Deutschlands. Sie wurden vor rund 10.000 Jahren im Nahen Osten zu Begleitern des Menschen, vermutlich weil sie Mäuse von den ersten Getreidevorräten fernhielten." },
  "02-18": { y: 1930, e: "🧊", t: "Pluto wird entdeckt", x: "Der 24-jährige Clyde Tombaugh verglich am Lowell-Observatorium in Arizona tagelang Fotoplatten des Nachthimmels. Schließlich entdeckte er einen Lichtpunkt, der sich bewegte: Pluto. Den Namen schlug ein elfjähriges Mädchen aus England vor. Seit 2006 gilt Pluto als Zwergplanet." },
  "02-19": { y: 1473, e: "☀️", t: "Nikolaus Kopernikus wird geboren", x: "Der in Thorn geborene Astronom Nikolaus Kopernikus stellte die Sonne statt der Erde in den Mittelpunkt des Planetensystems. Sein Hauptwerk erschien erst in seinem Todesjahr. Die kopernikanische Wende wurde zum Sinnbild für einen grundlegenden Wechsel der Sichtweise." },
  "02-20": { y: 1962, e: "🌎", t: "John Glenn umkreist die Erde", x: "Der Astronaut John Glenn umrundete in der Kapsel Friendship 7 dreimal die Erde, als erster Amerikaner im Orbit. Der Flug dauerte knapp fünf Stunden. 36 Jahre später flog er mit 77 Jahren noch einmal ins All und war damit lange der älteste Mensch im Weltraum." },
  "02-21": { e: "🗣️", t: "Tag der Muttersprache", x: "Heute ist Internationaler Tag der Muttersprache. Weltweit werden rund 7.000 Sprachen gesprochen, doch viele davon nur noch von wenigen, meist alten Menschen. Wenn eine Sprache verschwindet, gehen auch Geschichten, Wissen über Pflanzen und Tiere und eine eigene Art, die Welt zu sehen, verloren." },
  "02-22": { y: 1857, e: "📡", t: "Heinrich Hertz wird geboren", x: "Der Hamburger Physiker Heinrich Hertz wies als Erster elektromagnetische Wellen nach und zeigte, dass sie sich wie Licht verhalten. Er selbst hielt seine Entdeckung für praktisch nutzlos. Heute beruhen Radio, Mobilfunk und WLAN darauf, und die Einheit der Frequenz trägt seinen Namen: Hertz." },
  "02-23": { y: 1685, e: "🎺", t: "Georg Friedrich Händel wird geboren", x: "Der in Halle an der Saale geborene Komponist Händel machte vor allem in London Karriere. Sein Oratorium „Messiah“ mit dem berühmten Halleluja gehört zu den meistaufgeführten Chorwerken der Welt. Für den englischen König schrieb er die festliche Wassermusik für eine Bootsfahrt auf der Themse." },
  "02-24": { y: 1968, e: "💫", t: "Pulsare werden bekannt", x: "In der Fachzeitschrift Nature erschien die Entdeckung eines rätselhaften Signals, das mit großer Regelmäßigkeit pulsierte. Die Doktorandin Jocelyn Bell hatte es in ihren Messdaten bemerkt. Zunächst dachte man halb im Scherz an Außerirdische – tatsächlich waren es schnell rotierende Neutronensterne, sogenannte Pulsare." },
  "02-25": { y: 1841, e: "🎨", t: "Auguste Renoir wird geboren", x: "Der französische Maler Pierre-Auguste Renoir gehörte zu den Impressionisten, die das flüchtige Licht des Augenblicks einfangen wollten. Seine Bilder zeigen oft fröhliche Menschen beim Tanzen, Picknicken und Plaudern. Im Alter malte er trotz schwerer Gelenkkrankheit weiter, den Pinsel an der Hand festgebunden." },
  "02-26": { y: 1829, e: "👖", t: "Levi Strauss wird geboren", x: "Levi Strauss wurde im fränkischen Buttenheim geboren und wanderte als junger Mann nach Amerika aus. In San Francisco verkaufte er Stoffe an Goldgräber. Gemeinsam mit einem Schneider ließ er Arbeitshosen mit Metallnieten patentieren, die besonders haltbar waren – die ersten Jeans." },
  "02-27": { e: "🐻‍❄️", t: "Tag des Eisbären", x: "Heute ist Internationaler Tag des Eisbären. Eisbären jagen vor allem Robben vom Meereis aus. Wenn das Eis durch den Klimawandel früher schmilzt, müssen sie länger fasten. Unter ihrem weißen Fell ist ihre Haut übrigens schwarz, und die Haare selbst sind durchsichtig und hohl." },
  "02-28": { y: 1953, e: "🧬", t: "Die Doppelhelix", x: "In Cambridge fanden James Watson und Francis Crick heraus, wie das Erbmolekül DNA aufgebaut ist: als gewundene Doppelleiter. Entscheidend waren Röntgenaufnahmen der Forscherin Rosalind Franklin. Am selben Tag soll Crick im Pub verkündet haben, man habe das Geheimnis des Lebens gefunden." },
  "02-29": { e: "📅", t: "Schalttag", x: "Heute ist ein Schalttag, den es nur alle vier Jahre gibt. Die Erde braucht für eine Runde um die Sonne rund 365 Tage und knapp sechs Stunden. Ohne Schalttag würde der Kalender den Jahreszeiten davonlaufen. Wer heute Geburtstag hat, kann ihn nur in jedem vierten Jahr am eigentlichen Datum feiern." },
  "03-01": { e: "🌱", t: "Meteorologischer Frühlingsanfang", x: "Heute beginnt der Frühling – zumindest für Wetterdienste. Sie teilen das Jahr in ganze Monate ein, weil sich Statistiken so leichter vergleichen lassen. Der kalendarische Frühling beginnt dagegen erst um den 20. März mit der Tagundnachtgleiche. Bald blühen Krokusse, und die ersten Zugvögel kehren zurück." },
  "03-02": { y: 1969, e: "✈️", t: "Erstflug der Concorde", x: "Im französischen Toulouse hob die Concorde zu ihrem ersten Flug ab. Das britisch-französische Überschallflugzeug flog später mit mehr als doppelter Schallgeschwindigkeit von Europa nach New York in rund dreieinhalb Stunden. 2003 wurde der Betrieb wegen hoher Kosten eingestellt." },
  "03-03": { e: "🐆", t: "Tag des Artenschutzes", x: "Heute ist Welttag des Artenschutzes. An diesem Tag wurde 1973 ein internationales Abkommen unterzeichnet, das den Handel mit bedrohten Tieren und Pflanzen regelt. Wer aus dem Urlaub Souvenirs aus Elfenbein, Korallen oder Schildkrötenpanzer mitbringt, kann sich deshalb strafbar machen." },
  "03-04": { y: 1678, e: "🍂", t: "Antonio Vivaldi wird geboren", x: "Der Venezianer Antonio Vivaldi war Priester und Geigenvirtuose. Er unterrichtete an einem Waisenhaus, dessen Mädchenorchester berühmt war. Sein bekanntestes Werk, „Die vier Jahreszeiten“, malt mit Musik Vogelgesang, Gewitter, Jagd und klirrende Kälte." },
  "03-05": { y: 1512, e: "🗺️", t: "Gerhard Mercator wird geboren", x: "Der flämische Kartograf Gerhard Mercator entwickelte eine Kartenprojektion, auf der Kurse mit gleichbleibender Himmelsrichtung als gerade Linien erscheinen – ideal für Seefahrer. Dafür erscheinen Länder nahe den Polen stark vergrößert. Er prägte auch das Wort Atlas für eine Kartensammlung." },
  "03-06": { y: 1475, e: "🗿", t: "Michelangelo wird geboren", x: "Der italienische Künstler Michelangelo schuf die Marmorstatue des David und malte die Decke der Sixtinischen Kapelle in Rom – vier Jahre lang meist stehend auf einem Gerüst, den Kopf in den Nacken gelegt. Er sah sich selbst vor allem als Bildhauer." },
  "03-07": { y: 1875, e: "🥁", t: "Maurice Ravel wird geboren", x: "Der französische Komponist Maurice Ravel schrieb den „Boléro“: Eine einzige Melodie wiederholt sich immer wieder, nur die Instrumente wechseln, und die Musik wird immer lauter. Die kleine Trommel spielt dabei ununterbrochen denselben Rhythmus. Ravel selbst hielt das Stück für ein Experiment." },
  "03-08": { y: 1879, e: "⚛️", t: "Otto Hahn wird geboren", x: "Der Frankfurter Chemiker Otto Hahn entdeckte 1938 gemeinsam mit Fritz Straßmann die Kernspaltung. Die Physikerin Lise Meitner lieferte die entscheidende Erklärung. Hahn erhielt dafür den Nobelpreis für Chemie. Später warnte er eindringlich vor den Gefahren von Atomwaffen." },
  "03-09": { y: 1959, e: "👗", t: "Barbie kommt auf den Markt", x: "Auf einer Spielwarenmesse in New York wurde die Puppe Barbie vorgestellt. Die Erfinderin Ruth Handler hatte beobachtet, dass ihre Tochter Papierpuppen lieber als Erwachsene spielen ließ. Barbie hatte seitdem Hunderte Berufe – darunter Astronautin, lange bevor eine Amerikanerin ins All flog." },
  "03-10": { y: 1876, e: "☎️", t: "Das erste Telefongespräch", x: "Alexander Graham Bell sprach in sein neues Gerät: Mr. Watson, kommen Sie her, ich möchte Sie sehen. Sein Assistent im Nebenraum hörte die Worte durch den Draht. Es war das erste erfolgreiche Telefongespräch. Wenige Tage zuvor hatte Bell sein Patent erhalten." },
  "03-11": { y: 1921, e: "💃", t: "Astor Piazzolla wird geboren", x: "Der Argentinier Astor Piazzolla spielte das Bandoneon, eine Art Handzuginstrument, das ursprünglich aus Deutschland stammt. Er verband den traditionellen Tango mit Jazz und klassischer Musik und schuf den Tango Nuevo. Seine Stücke werden heute in Konzertsälen auf der ganzen Welt gespielt." },
  "03-12": { y: 1989, e: "🌐", t: "Die Idee des World Wide Web", x: "Tim Berners-Lee reichte am Forschungszentrum CERN einen Vorschlag ein, wie Forscher Informationen über verknüpfte Seiten austauschen könnten. Sein Vorgesetzter notierte darauf: vage, aber spannend. Aus der Idee wurde das World Wide Web, das Berners-Lee später lizenzfrei für alle freigab." },
  "03-13": { y: 1781, e: "🪐", t: "Uranus wird entdeckt", x: "Der aus Hannover stammende Musiker und Astronom Wilhelm Herschel entdeckte mit einem selbst gebauten Teleskop in England einen neuen Himmelskörper. Zunächst hielt er ihn für einen Kometen, doch es war ein Planet: Uranus. Es war der erste Planet, der mit einem Teleskop gefunden wurde." },
  "03-14": { e: "🥧", t: "Pi-Tag", x: "Heute ist Pi-Tag, weil das Datum in amerikanischer Schreibweise 3/14 lautet, die ersten Ziffern der Kreiszahl Pi. Pi gibt an, wie oft der Durchmesser in den Umfang eines Kreises passt, und hat unendlich viele Nachkommastellen ohne Muster. Passend dazu wurde an einem 14. März Albert Einstein geboren." },
  "03-15": { e: "🛒", t: "Weltverbrauchertag", x: "Heute ist Weltverbrauchertag. Verbraucherschutz sorgt etwa dafür, dass Lebensmittel gekennzeichnet sind, Produkte sicher sind und man Online-Käufe in der Regel binnen 14 Tagen widerrufen kann. Verbraucherzentralen beraten bei Problemen mit Verträgen, Energieanbietern oder Abofallen." },
  "03-16": { y: 1926, e: "🚀", t: "Die erste Flüssigkeitsrakete", x: "Der amerikanische Physiker Robert Goddard startete auf einem Feld in Massachusetts die erste Rakete mit flüssigem Treibstoff. Sie flog nur zweieinhalb Sekunden und rund zwölf Meter hoch. Doch das Prinzip, Benzin und flüssigen Sauerstoff zu verbrennen, führte Jahrzehnte später bis zum Mond." },
  "03-17": { e: "☘️", t: "St. Patrick’s Day", x: "Heute feiern Iren auf der ganzen Welt den St. Patrick’s Day zu Ehren ihres Schutzheiligen. Das Kleeblatt ist sein Symbol, und vielerorts wird alles grün gefärbt – in Chicago sogar ein ganzer Fluss. Die großen Paraden entstanden übrigens zuerst bei irischen Auswanderern in Amerika." },
  "03-18": { y: 1965, e: "🧑‍🚀", t: "Der erste Weltraumspaziergang", x: "Der sowjetische Kosmonaut Alexei Leonow verließ als erster Mensch ein Raumschiff und schwebte gut zehn Minuten im All, nur durch eine Leine gesichert. Danach hatte sich sein Anzug so aufgebläht, dass er nicht mehr in die Luftschleuse passte. Er ließ heimlich Luft ab, um sich hineinzuzwängen." },
  "03-19": { y: 1932, e: "🌉", t: "Die Hafenbrücke von Sydney", x: "In Sydney wurde die Harbour Bridge eröffnet, eine gewaltige Stahlbogenbrücke über den Hafen. Die Einheimischen nennen sie wegen ihrer Form den Kleiderbügel. Um sie vor Rost zu schützen, wird sie ständig neu gestrichen. Heute kann man mit Führung sogar über den Bogen klettern." },
  "03-20": { e: "🌷", t: "Frühlingsanfang", x: "Um den 20. März ist Tagundnachtgleiche: Die Sonne steht genau über dem Äquator, und Tag und Nacht sind überall auf der Erde etwa gleich lang. Damit beginnt auf der Nordhalbkugel der astronomische Frühling. Von nun an sind die Tage länger als die Nächte – bis zum Sommeranfang im Juni." },
  "03-21": { e: "🌲", t: "Tag des Waldes", x: "Heute ist Internationaler Tag des Waldes. Rund ein Drittel der Fläche Deutschlands ist bewaldet. Wälder speichern Kohlenstoff, filtern Wasser, kühlen die Umgebung und bieten Tausenden Arten Lebensraum. Durch Dürre, Stürme und Borkenkäfer sind viele Wälder in den letzten Jahren stark geschädigt worden." },
  "03-22": { e: "💧", t: "Weltwassertag", x: "Heute ist Weltwassertag. Nur rund 2,5 Prozent des Wassers auf der Erde ist Süßwasser, und das meiste davon ist in Gletschern und Eis gebunden. Noch immer haben rund zwei Milliarden Menschen keinen sicheren Zugang zu sauberem Trinkwasser. In Deutschland kommt es in bester Qualität aus dem Hahn." },
  "03-23": { e: "🌦️", t: "Welttag der Meteorologie", x: "Heute ist Welttag der Meteorologie, zur Erinnerung an die Gründung der Weltorganisation für Meteorologie. Wetterdienste aller Länder tauschen rund um die Uhr Messdaten aus – denn das Wetter macht an keiner Grenze halt. Eine Vorhersage für fünf Tage ist heute etwa so zuverlässig wie vor rund 40 Jahren eine für den nächsten Tag." },
  "03-24": { y: 1882, e: "🔬", t: "Der Tuberkulose-Erreger", x: "Robert Koch verkündete in Berlin, dass er den Erreger der Tuberkulose gefunden hatte, damals eine der häufigsten Todesursachen. Seine Entdeckung war ein Meilenstein der Bakteriologie. Zur Erinnerung ist der 24. März heute Welttuberkulosetag, denn die Krankheit ist weltweit noch immer verbreitet." },
  "03-25": { y: 1655, e: "🪐", t: "Titan wird entdeckt", x: "Der niederländische Gelehrte Christiaan Huygens entdeckte mit einem selbst geschliffenen Teleskop den größten Mond des Saturn: Titan. Er erkannte außerdem als Erster, dass Saturn von einem Ring umgeben ist. Nach ihm wurde später die Sonde benannt, die auf Titan landete." },
  "03-26": { y: 1953, e: "💉", t: "Impfstoff gegen Kinderlähmung", x: "Der amerikanische Arzt Jonas Salk verkündete im Radio, dass er einen Impfstoff gegen Kinderlähmung entwickelt hatte. Die Krankheit lähmte damals jedes Jahr Tausende Kinder. Salk ließ den Impfstoff nicht patentieren. Heute ist die Kinderlähmung dank weltweiter Impfkampagnen fast ausgerottet." },
  "03-27": { e: "🎭", t: "Welttheatertag", x: "Heute ist Welttheatertag. Theater gibt es seit Jahrtausenden: Schon im antiken Athen strömten Tausende zu Tragödien und Komödien in riesige Freilufttheater. Deutschland hat eine der dichtesten Theaterlandschaften der Welt mit weit über hundert öffentlich getragenen Bühnen." },
  "03-28": { y: 1592, e: "📖", t: "Comenius wird geboren", x: "Der tschechische Gelehrte Johann Amos Comenius forderte, dass alle Kinder – Jungen wie Mädchen, arm wie reich – zur Schule gehen sollten, und zwar mit Freude statt mit Prügeln. Er schrieb das erste Bilderbuch für Kinder, in dem Wörter mit Bildern erklärt wurden. Er gilt als Vater der modernen Pädagogik." },
  "03-29": { y: 1974, e: "☀️", t: "Besuch beim Merkur", x: "Die Raumsonde Mariner 10 flog als erste am Merkur vorbei, dem sonnennächsten Planeten. Ihre Bilder zeigten eine von Kratern übersäte Oberfläche, die dem Mond ähnelt. Mariner 10 nutzte als erste Sonde die Schwerkraft eines anderen Planeten, der Venus, um Kurs und Tempo zu ändern." },
  "03-30": { y: 1853, e: "🌻", t: "Vincent van Gogh wird geboren", x: "Der niederländische Maler Vincent van Gogh schuf in nur rund zehn Jahren über 800 Gemälde, darunter „Die Sternennacht“ und seine Sonnenblumen. Zu Lebzeiten verkaufte er kaum Bilder und lebte oft von der Unterstützung seines Bruders Theo. Heute zählen seine Werke zu den teuersten der Welt." },
  "03-31": { y: 1889, e: "🗼", t: "Der Eiffelturm ist fertig", x: "In Paris wurde der Eiffelturm für die Weltausstellung fertiggestellt. Mit rund 300 Metern war er damals das höchste Bauwerk der Welt. Viele Künstler protestierten gegen das eiserne Ungetüm, und eigentlich sollte er nach 20 Jahren abgerissen werden. Er blieb, weil er als Funkturm nützlich war." },
  "04-01": { y: 1957, e: "🍝", t: "Die Spaghetti-Ernte", x: "Die BBC zeigte einen Bericht über Bauern in der Schweiz, die Spaghetti von Bäumen ernteten. Weil Nudeln in Großbritannien damals wenig bekannt waren, riefen viele Zuschauer an und fragten, wie sie selbst einen Spaghettibaum anbauen könnten. Der Beitrag gilt als einer der berühmtesten Aprilscherze." },
  "04-02": { y: 1805, e: "🧜", t: "Tag des Kinderbuchs", x: "Am 2. April 1805 wurde der dänische Dichter Hans Christian Andersen geboren. Er schrieb Märchen wie „Die kleine Meerjungfrau“, „Des Kaisers neue Kleider“ und „Das hässliche Entlein“. Zu seinen Ehren ist heute Internationaler Kinderbuchtag." },
  "04-03": { y: 1973, e: "📞", t: "Das erste Handygespräch", x: "Der Ingenieur Martin Cooper von Motorola rief auf einer Straße in New York mit einem tragbaren Telefon an – ausgerechnet bei einem Konkurrenten. Das Gerät wog über ein Kilogramm, und der Akku reichte für rund 30 Minuten Gespräch. Zehn Jahre später kam das erste Handy in den Handel." },
  "04-04": { y: 1975, e: "💻", t: "Microsoft wird gegründet", x: "Die jungen Programmierer Bill Gates und Paul Allen gründeten in Albuquerque in New Mexico das Unternehmen Microsoft. Zunächst schrieben sie Software für einen Bausatz-Computer. Mit dem Betriebssystem Windows wurde Microsoft später zu einem der größten Unternehmen der Welt." },
  "04-05": { y: 1827, e: "🧼", t: "Joseph Lister wird geboren", x: "Der englische Chirurg Joseph Lister erkannte, dass Keime Wundinfektionen verursachen. Er reinigte Instrumente, Wunden und Verbände mit Karbolsäure – die Zahl der Todesfälle nach Operationen sank drastisch. Er gilt als Begründer der keimfreien Chirurgie." },
  "04-06": { y: 1896, e: "🏅", t: "Die ersten modernen Olympischen Spiele", x: "In Athen wurden die ersten Olympischen Spiele der Neuzeit eröffnet, angeregt vom Franzosen Pierre de Coubertin. Rund 240 Sportler aus 14 Ländern nahmen teil, ausschließlich Männer. Die Sieger erhielten übrigens eine Silbermedaille und einen Olivenzweig – Goldmedaillen gab es erst später." },
  "04-07": { e: "🩺", t: "Weltgesundheitstag", x: "Heute ist Weltgesundheitstag, zur Erinnerung an die Gründung der Weltgesundheitsorganisation im Jahr 1948. Die Lebenserwartung ist weltweit in den letzten hundert Jahren enorm gestiegen, vor allem dank sauberem Wasser, Impfungen und besserer Ernährung. Doch die Unterschiede zwischen Ländern sind noch immer groß." },
  "04-08": { y: 1911, e: "❄️", t: "Supraleitung entdeckt", x: "Der niederländische Physiker Heike Kamerlingh Onnes kühlte Quecksilber auf rund minus 269 Grad ab und stellte fest, dass sein elektrischer Widerstand plötzlich vollständig verschwand. Diese Supraleitung nutzt man heute in Kernspintomografen im Krankenhaus und in Teilchenbeschleunigern." },
  "04-09": { y: 1806, e: "🌉", t: "Isambard Kingdom Brunel wird geboren", x: "Der britische Ingenieur Brunel baute Brücken, Tunnel, Eisenbahnlinien und riesige Dampfschiffe. Sein Schiff Great Eastern war jahrzehntelang das größte der Welt und verlegte später das erste dauerhafte Telegrafenkabel durch den Atlantik. Auf Fotos trägt er meist einen hohen Zylinder." },
  "04-10": { y: 2019, e: "🕳️", t: "Das erste Foto eines Schwarzen Lochs", x: "Forscher veröffentlichten das erste Bild eines Schwarzen Lochs: einen leuchtenden Ring um einen dunklen Schatten im Zentrum der Galaxie M87. Dafür wurden Radioteleskope auf der ganzen Welt zu einem virtuellen Teleskop so groß wie die Erde zusammengeschaltet. Die Datenmenge wurde auf Festplatten per Flugzeug verschickt." },
  "04-11": { e: "🧠", t: "Welt-Parkinson-Tag", x: "Heute ist Welt-Parkinson-Tag, am Geburtstag des englischen Arztes James Parkinson, der die Krankheit 1817 erstmals genau beschrieb. Bei Parkinson sterben Nervenzellen ab, die den Botenstoff Dopamin bilden. Typisch sind Zittern, steife Muskeln und verlangsamte Bewegungen. Medikamente können die Beschwerden lindern." },
  "04-12": { y: 1961, e: "🚀", t: "Der erste Mensch im All", x: "Der sowjetische Kosmonaut Juri Gagarin umrundete in der Kapsel Wostok 1 einmal die Erde. Der Flug dauerte 108 Minuten. Vor dem Start rief er: Poyekhali! – Los geht’s! Zur Erinnerung ist der 12. April heute der Internationale Tag der bemannten Raumfahrt." },
  "04-13": { y: 1742, e: "🎶", t: "Uraufführung des Messiah", x: "In Dublin wurde Händels Oratorium „Messiah“ uraufgeführt. Weil der Saal überfüllt zu werden drohte, baten die Veranstalter die Herren, ohne Degen, und die Damen, ohne weite Reifröcke zu kommen. Der Erlös ging an wohltätige Zwecke. Heute steht bei der Halleluja-Stelle in manchen Ländern das Publikum auf." },
  "04-14": { y: 2003, e: "🧬", t: "Das menschliche Erbgut ist entziffert", x: "Das internationale Humangenomprojekt verkündete, dass die Abfolge der rund drei Milliarden Bausteine des menschlichen Erbguts weitgehend entschlüsselt sei. Das Projekt hatte 13 Jahre gedauert. Heute lässt sich ein vollständiges Genom in wenigen Stunden und für einen Bruchteil der Kosten lesen." },
  "04-15": { y: 1452, e: "🎨", t: "Leonardo da Vinci wird geboren", x: "Leonardo da Vinci war Maler, Erfinder, Anatom und Ingenieur zugleich. Er malte die Mona Lisa, entwarf Flugmaschinen und studierte den menschlichen Körper. Seine Notizen schrieb er in Spiegelschrift. An seinem Geburtstag wird heute der Welttag der Kunst gefeiert." },
  "04-16": { y: 1889, e: "🎩", t: "Charlie Chaplin wird geboren", x: "Der in London geborene Charlie Chaplin wurde mit seiner Figur des Tramps – Melone, Spazierstock, zu große Schuhe – zum ersten Weltstar des Films. In Stummfilmen brachte er Menschen allein mit Gesten und Mimik zum Lachen und Weinen. Er schrieb, spielte, führte Regie und komponierte die Musik oft selbst." },
  "04-17": { y: 1970, e: "🛟", t: "Apollo 13 kehrt heim", x: "Die drei Astronauten von Apollo 13 landeten sicher im Pazifik. Auf dem Weg zum Mond war ein Sauerstofftank explodiert, und die Mondlandung musste abgebrochen werden. Mit viel Improvisation – etwa einem Luftfilter aus Pappe, Plastik und Klebeband – brachten Crew und Bodenteam das Raumschiff zurück." },
  "04-18": { e: "🏛️", t: "Tag des Denkmals", x: "Heute ist Internationaler Denkmaltag. Die UNESCO-Welterbeliste umfasst über tausend Stätten, darunter Naturwunder wie das Great Barrier Reef und Bauwerke wie den Kölner Dom. Deutschland gehört zu den Ländern mit den meisten Welterbestätten, zum Beispiel das Wattenmeer und die Zeche Zollverein." },
  "04-19": { y: 1971, e: "🛰️", t: "Die erste Raumstation", x: "Die Sowjetunion startete Saljut 1, die erste Raumstation der Welt. Einige Wochen später lebte dort eine dreiköpfige Besatzung mehr als drei Wochen lang. Seitdem wurden immer größere Stationen gebaut – bis zur Internationalen Raumstation, die seit dem Jahr 2000 ständig bewohnt ist." },
  "04-20": { e: "🀄", t: "Tag der chinesischen Sprache", x: "Heute ist der Tag der chinesischen Sprache. Chinesisch hat mehr Muttersprachler als jede andere Sprache. Die Schrift verwendet Tausende Zeichen statt eines Alphabets; für eine Zeitung braucht man etwa 3.000. Im Hochchinesischen verändert zudem die Tonhöhe die Bedeutung einer Silbe." },
  "04-21": { y: 1782, e: "🧸", t: "Friedrich Fröbel wird geboren", x: "Der Thüringer Pädagoge Friedrich Fröbel gründete 1840 eine Einrichtung, in der Kinder spielerisch lernen sollten, und nannte sie Kindergarten. Er entwickelte auch Spielgaben wie Bausteine und Bälle. Das Wort Kindergarten wurde später unverändert ins Englische und viele andere Sprachen übernommen." },
  "04-22": { y: 1970, e: "🌍", t: "Tag der Erde", x: "In den USA gingen am ersten Earth Day rund 20 Millionen Menschen für den Umweltschutz auf die Straße. Heute wird der Tag der Erde in fast allen Ländern der Welt begangen. Er erinnert daran, dass saubere Luft, sauberes Wasser und gesunde Böden die Grundlage allen Lebens sind." },
  "04-23": { e: "📚", t: "Welttag des Buches", x: "Heute ist Welttag des Buches. Das Datum stammt aus Katalonien, wo man sich an diesem Tag Rosen und Bücher schenkt. Passend dazu starben 1616 um diese Zeit die Dichter William Shakespeare und Miguel de Cervantes. In Deutschland erhalten viele Schulkinder an diesem Tag ein Buch geschenkt." },
  "04-24": { y: 1990, e: "🔭", t: "Hubble startet ins All", x: "Das Weltraumteleskop Hubble wurde mit dem Space Shuttle in eine Umlaufbahn gebracht. Zunächst lieferte es unscharfe Bilder, weil sein Spiegel um den Bruchteil einer Haaresbreite falsch geschliffen war. Astronauten bauten 1993 eine Korrekturoptik ein. Seitdem hat Hubble Millionen Beobachtungen gemacht." },
  "04-25": { e: "🐧", t: "Weltpinguintag", x: "Heute ist Weltpinguintag – ungefähr zu dieser Zeit beginnen Adeliepinguine in der Antarktis ihre Wanderung nach Norden. Alle Pinguinarten leben auf der Südhalbkugel. Ihre Flügel sind zu Flossen geworden, mit denen sie unter Wasser regelrecht fliegen. Kaiserpinguine tauchen über 500 Meter tief." },
  "04-26": { y: 1785, e: "🦅", t: "John James Audubon wird geboren", x: "Der Naturforscher John James Audubon reiste durch Nordamerika und malte fast 500 Vogelarten in Lebensgröße. Sein Werk „Birds of America“ gehört zu den teuersten Büchern der Welt. Nach ihm ist eine der größten Vogelschutzorganisationen der USA benannt." },
  "04-27": { e: "✏️", t: "Welttag des Designs", x: "Heute ist Welttag des Designs. Gutes Design macht Dinge nicht nur schön, sondern verständlich und benutzbar – vom Stuhl über Verkehrsschilder bis zur App. Einflussreich war die deutsche Kunstschule Bauhaus, die ab 1919 Kunst und Handwerk verband und klare, schlichte Formen prägte." },
  "04-28": { y: 1947, e: "🛶", t: "Die Kon-Tiki legt ab", x: "Der norwegische Forscher Thor Heyerdahl stach mit fünf Begleitern von Peru aus auf einem Floß aus Balsaholz in See. Er wollte zeigen, dass Menschen in alter Zeit über den Pazifik gelangt sein könnten. Nach 101 Tagen und rund 7.000 Kilometern strandeten sie auf einem Riff in Polynesien." },
  "04-29": { e: "💃", t: "Welttanztag", x: "Heute ist Welttanztag, am Geburtstag des französischen Ballettmeisters Jean-Georges Noverre. Tanzen gibt es in allen Kulturen der Welt. Forscher haben herausgefunden, dass gemeinsames Tanzen im Takt das Gemeinschaftsgefühl stärkt und sogar die Schmerzempfindlichkeit senken kann." },
  "04-30": { y: 1777, e: "🔢", t: "Carl Friedrich Gauß wird geboren", x: "Der in Braunschweig geborene Gauß gilt als einer der größten Mathematiker aller Zeiten. Der Legende nach addierte er als Schüler blitzschnell alle Zahlen von 1 bis 100, indem er Paare bildete. Er vermaß zudem das Königreich Hannover und erforschte den Magnetismus der Erde." },
  "05-01": { y: 1851, e: "🏢", t: "Der Kristallpalast", x: "In London eröffnete die erste Weltausstellung in einem riesigen Gebäude aus Glas und Eisen, dem Kristallpalast. Er war in nur wenigen Monaten aus vorgefertigten Teilen errichtet worden. Über sechs Millionen Besucher bestaunten Maschinen, Erfindungen und Waren aus aller Welt." },
  "05-02": { e: "🐟", t: "Welt-Thunfisch-Tag", x: "Heute ist Welt-Thunfisch-Tag. Thunfische sind schnelle Langstreckenschwimmer, die ganze Ozeane durchqueren. Anders als die meisten Fische können sie ihren Körper wärmer halten als das Wasser. Einige Arten wurden stark überfischt; strengere Fangquoten haben manchen Beständen inzwischen geholfen." },
  "05-03": { y: 1896, e: "🐶", t: "Dodie Smith wird geboren", x: "Die englische Schriftstellerin Dodie Smith schrieb den Roman „Hundertundeins Dalmatiner“ über einen Hundehaushalt, dessen Welpen gestohlen werden. Sie selbst hielt Dalmatiner, einer davon hieß Pongo. Walt Disney verfilmte das Buch 1961 als Zeichentrickfilm." },
  "05-04": { e: "🌌", t: "Star-Wars-Tag", x: "Heute ist Star-Wars-Tag, wegen eines Wortspiels: May the Fourth klingt auf Englisch wie der berühmte Filmsatz Möge die Macht mit dir sein. Der erste Star-Wars-Film kam 1977 in die Kinos und revolutionierte mit seinen Spezialeffekten das Science-Fiction-Kino." },
  "05-05": { y: 1961, e: "🚀", t: "Der erste Amerikaner im All", x: "Alan Shepard flog in der Kapsel Freedom 7 als erster Amerikaner ins All. Der Flug dauerte nur rund 15 Minuten und führte nicht um die Erde, sondern in einem Bogen hinauf und zurück. Vor dem Start musste er stundenlang warten – und durfte die Kapsel nicht verlassen." },
  "05-06": { y: 1856, e: "🛋️", t: "Sigmund Freud wird geboren", x: "Der Wiener Arzt Sigmund Freud begründete die Psychoanalyse. Er glaubte, dass unbewusste Wünsche und Konflikte unser Verhalten prägen, und ließ Patienten auf einer Couch frei erzählen. Viele seiner Theorien gelten heute als überholt, doch die Idee der Gesprächstherapie wirkt bis heute." },
  "05-07": { y: 1833, e: "🎼", t: "Johannes Brahms wird geboren", x: "In Hamburg kam der Komponist Johannes Brahms zur Welt. Sein Wiegenlied „Guten Abend, gut’ Nacht“ kennt fast jedes Kind. Am selben Tag, sieben Jahre später, wurde übrigens der russische Komponist Peter Tschaikowsky geboren, der unter anderem „Schwanensee“ und „Der Nussknacker“ schrieb." },
  "05-08": { y: 1926, e: "🦍", t: "David Attenborough wird geboren", x: "Der britische Naturfilmer David Attenborough brachte Generationen von Zuschauern die Tier- und Pflanzenwelt nahe, mit Serien wie „Das Leben auf der Erde“ und „Unser blauer Planet“. Mehrere Tierarten und sogar ein Forschungsschiff wurden nach ihm benannt. Er warnt eindringlich vor dem Verlust der Artenvielfalt." },
  "05-09": { y: 1860, e: "🧚", t: "J. M. Barrie wird geboren", x: "Der schottische Schriftsteller James Matthew Barrie erfand Peter Pan, den Jungen, der nie erwachsen werden will, und die Fee Tinker Bell. Die Rechte an Peter Pan schenkte er einem Kinderkrankenhaus in London, das bis heute von den Einnahmen profitiert." },
  "05-10": { y: 1869, e: "🚂", t: "Die Eisenbahn quer durch Amerika", x: "In Utah wurden die Gleise zweier Eisenbahngesellschaften verbunden, die sich von Osten und Westen aufeinander zugearbeitet hatten. Ein goldener Nagel wurde symbolisch eingeschlagen. Nun konnte man in rund einer Woche von der Ost- zur Westküste reisen statt in mehreren Monaten." },
  "05-11": { y: 1997, e: "♟️", t: "Computer schlägt Weltmeister", x: "In der letzten Partie ihres Rückkampfs besiegte der IBM-Computer Deep Blue den Schachweltmeister Garri Kasparow. Damit gewann erstmals ein Computer ein Match gegen einen amtierenden Weltmeister unter Turnierbedingungen. Deep Blue berechnete rund 200 Millionen Stellungen pro Sekunde." },
  "05-12": { y: 1820, e: "🏮", t: "Tag der Pflegenden", x: "Am 12. Mai 1820 wurde Florence Nightingale geboren. Sie verbesserte die Hygiene in Lazaretten und senkte so die Sterblichkeit drastisch. Sie gründete eine Pflegeschule und nutzte als eine der Ersten Diagramme, um mit Statistik zu überzeugen. Heute ist ihr Geburtstag Internationaler Tag der Pflegenden." },
  "05-13": { y: 1857, e: "🦟", t: "Ronald Ross wird geboren", x: "Der britische Arzt Ronald Ross wies nach, dass Malaria von Mücken übertragen wird. Er fand die Erreger im Magen von Stechmücken, die an Kranken gesaugt hatten. Dafür erhielt er 1902 den Nobelpreis. Die Erkenntnis ermöglichte die Bekämpfung der Krankheit, etwa mit Moskitonetzen." },
  "05-14": { y: 1796, e: "🐄", t: "Die erste Impfung", x: "Der englische Landarzt Edward Jenner ritzte einem achtjährigen Jungen Material aus einer Kuhpockenblase in die Haut. Später setzte er ihn den gefährlichen Pocken aus – der Junge erkrankte nicht. Das Wort Vakzin für Impfstoff kommt vom lateinischen vacca, Kuh. 1980 wurden die Pocken für ausgerottet erklärt." },
  "05-15": { y: 1859, e: "🧲", t: "Pierre Curie wird geboren", x: "Der französische Physiker Pierre Curie erforschte Kristalle und Magnetismus und entdeckte mit seiner Frau Marie die Elemente Polonium und Radium. Gemeinsam erhielten sie 1903 den Nobelpreis für Physik. Eine Einheit für Radioaktivität, das Curie, erinnert an das Forscherpaar." },
  "05-16": { y: 1960, e: "🔦", t: "Tag des Lichts", x: "Am 16. Mai 1960 brachte der amerikanische Physiker Theodore Maiman den ersten Laser zum Leuchten. Anfangs nannte man ihn eine Lösung, die ein Problem sucht. Heute stecken Laser in Scannern, Glasfaserleitungen, Augenoperationen und Messgeräten. Zur Erinnerung ist heute Internationaler Tag des Lichts." },
  "05-17": { y: 1865, e: "📡", t: "Welttag der Telekommunikation", x: "An diesem Tag wurde 1865 in Paris der Internationale Telegrafenverein gegründet, damit Telegramme über Landesgrenzen hinweg nach gemeinsamen Regeln verschickt werden konnten. Daraus wurde die Internationale Fernmeldeunion, eine der ältesten internationalen Organisationen. Sie koordiniert heute etwa Funkfrequenzen und Satellitenbahnen." },
  "05-18": { e: "🏺", t: "Internationaler Museumstag", x: "Heute ist Internationaler Museumstag. Deutschland hat über 6.000 Museen – mehr als es Kinos gibt. Neben Kunst- und Geschichtsmuseen gibt es auch ungewöhnliche, etwa ein Museum über Brot in Ulm, oder riesige wie das Deutsche Museum in München, eines der größten Technikmuseen der Welt." },
  "05-19": { y: 1910, e: "☄️", t: "Durch den Schweif des Halleyschen Kometen", x: "Die Erde zog durch den Schweif des Halleyschen Kometen. Astronomen hatten darin giftiges Gas nachgewiesen, und manche Menschen gerieten in Panik. Findige Händler verkauften sogar Kometenpillen und Gasmasken. Tatsächlich war das Gas so extrem verdünnt, dass niemand etwas bemerkte." },
  "05-20": { e: "🐝", t: "Weltbienentag", x: "Heute ist Weltbienentag, am Geburtstag des slowenischen Imkers Anton Janša. Bienen und andere Insekten bestäuben einen Großteil unserer Nutzpflanzen, etwa Äpfel, Kirschen und Raps. Neben der Honigbiene gibt es in Deutschland über 500 Wildbienenarten, von denen viele gefährdet sind." },
  "05-21": { y: 1471, e: "🐇", t: "Albrecht Dürer wird geboren", x: "Der Nürnberger Künstler Albrecht Dürer malte und druckte Werke von erstaunlicher Detailgenauigkeit. Sein Aquarell eines Feldhasen zeigt jedes einzelne Haar, und im Auge spiegelt sich ein Fenster. Er malte sich als einer der ersten Künstler immer wieder selbst." },
  "05-22": { e: "🦋", t: "Tag der biologischen Vielfalt", x: "Heute ist Internationaler Tag der biologischen Vielfalt. Wissenschaftler haben bislang rund zwei Millionen Arten beschrieben, doch vermutlich gibt es viele Millionen mehr, besonders Insekten und Mikroorganismen. Gleichzeitig sterben Arten heute deutlich schneller aus als im natürlichen Durchschnitt." },
  "05-23": { y: 1707, e: "🌼", t: "Carl von Linné wird geboren", x: "Der schwedische Naturforscher Carl von Linné gab jedem Lebewesen einen zweiteiligen lateinischen Namen, etwa Homo sapiens für den Menschen. Dieses einfache System wird bis heute weltweit verwendet. Er soll sogar eine Blumenuhr entworfen haben, deren Blüten sich zu unterschiedlichen Stunden öffnen." },
  "05-24": { y: 1844, e: "📟", t: "Die erste Telegrafenleitung", x: "Samuel Morse schickte über eine Leitung von Washington nach Baltimore die Nachricht: Was hat Gott gewirkt! Die Punkte und Striche seines Morsealphabets kamen in Sekunden an, wofür ein Reiter Stunden gebraucht hätte. Innerhalb weniger Jahrzehnte überzog ein Telegrafennetz die Kontinente." },
  "05-25": { e: "🧺", t: "Handtuchtag", x: "Heute ist Handtuchtag, zu Ehren des Schriftstellers Douglas Adams. In seinem Roman „Per Anhalter durch die Galaxis“ heißt es, ein Handtuch sei der nützlichste Gegenstand für Reisende durchs All. Fans tragen heute ein Handtuch mit sich. Die Zahl 42 ist dort übrigens die Antwort auf alle Fragen." },
  "05-26": { y: 1951, e: "👩‍🚀", t: "Sally Ride wird geboren", x: "Die amerikanische Physikerin Sally Ride flog 1983 als erste Amerikanerin ins All. Vor dem Flug fragten Journalisten sie, ob sie im Weltraum weinen werde. Nach ihrer Karriere setzte sie sich dafür ein, dass sich mehr Mädchen für Naturwissenschaften begeistern." },
  "05-27": { y: 1907, e: "🐦", t: "Rachel Carson wird geboren", x: "Die amerikanische Biologin Rachel Carson beschrieb in ihrem Buch „Der stumme Frühling“ 1962, wie Insektengifte wie DDT Vögel und andere Tiere töteten. Das Buch rüttelte die Öffentlichkeit auf und gilt als ein Ausgangspunkt der modernen Umweltbewegung. DDT wurde später in vielen Ländern verboten." },
  "05-28": { y: 1937, e: "🌁", t: "Die Golden Gate Bridge", x: "In San Francisco wurde die Golden Gate Bridge für Autos freigegeben, nachdem am Tag zuvor bereits Fußgänger darüberlaufen durften. Damals war sie die längste Hängebrücke der Welt. Ihre Farbe heißt International Orange und wurde gewählt, weil sie im häufigen Nebel gut zu sehen ist." },
  "05-29": { y: 1953, e: "🏔️", t: "Auf dem Gipfel der Welt", x: "Der Neuseeländer Edmund Hillary und der Sherpa Tenzing Norgay standen als erste Menschen auf dem Gipfel des Mount Everest, des höchsten Bergs der Erde. Sie blieben nur rund 15 Minuten oben. Tenzing hinterließ Süßigkeiten als Gabe, Hillary ein kleines Kreuz." },
  "05-30": { y: 1846, e: "🥚", t: "Peter Carl Fabergé wird geboren", x: "Der Goldschmied Peter Carl Fabergé fertigte in Sankt Petersburg kunstvolle Schmuckeier aus Gold, Emaille und Edelsteinen. In jedem Ei steckte eine Überraschung, etwa eine winzige Kutsche oder ein mechanischer Vogel. Heute sind die Fabergé-Eier Millionen wert." },
  "05-31": { e: "🚭", t: "Weltnichtrauchertag", x: "Heute ist Weltnichtrauchertag. Tabak enthält Tausende Chemikalien, darunter viele krebserregende. In Deutschland sterben jedes Jahr über 100.000 Menschen an den Folgen des Rauchens. Wer aufhört, profitiert schnell: Schon nach einem Jahr sinkt das Risiko für Herzkrankheiten deutlich." },
  "06-01": { e: "🥛", t: "Weltmilchtag", x: "Heute ist Weltmilchtag. Eine Kuh gibt heute in Deutschland im Durchschnitt über 8.000 Liter Milch im Jahr – ein Vielfaches früherer Zeiten. Dass viele Erwachsene Milch überhaupt vertragen, verdanken sie einer Genveränderung, die sich erst nach Beginn der Viehhaltung ausbreitete." },
  "06-02": { y: 1857, e: "🎻", t: "Edward Elgar wird geboren", x: "Der englische Komponist Edward Elgar schrieb die Enigma-Variationen, in denen jede Variation einen Freund musikalisch porträtiert. Berühmt wurde auch sein Marsch „Pomp and Circumstance“. Er brachte sich das Komponieren weitgehend selbst bei, im Musikgeschäft seines Vaters." },
  "06-03": { e: "🚲", t: "Weltfahrradtag", x: "Heute ist Weltfahrradtag. Das Fahrrad ist eines der effizientesten Verkehrsmittel überhaupt: Ein Radfahrer braucht für dieselbe Strecke weniger Energie als ein Fußgänger. Seinen Vorläufer, die Laufmaschine ohne Pedale, erfand Karl Drais 1817 in Mannheim." },
  "06-04": { y: 1896, e: "🚙", t: "Henry Fords erstes Auto", x: "In der Nacht fuhr Henry Ford in Detroit zum ersten Mal mit seinem selbst gebauten Quadricycle, einem Wagen auf vier Fahrradrädern. Weil das Fahrzeug zu breit für die Werkstatttür war, riss er kurzerhand einen Teil der Wand ein. Später machte er das Auto mit dem Fließband erschwinglich." },
  "06-05": { e: "🌿", t: "Tag der Umwelt", x: "Heute ist Weltumwelttag. Seit 1974 lenken die Vereinten Nationen an diesem Tag den Blick auf Umweltprobleme wie Plastikmüll, Luftverschmutzung und das Artensterben. Jeder Mensch in Deutschland verursacht über 200 Kilogramm Verpackungsmüll im Jahr – ein Wert, der sich mit Mehrweg deutlich senken lässt." },
  "06-06": { y: 1933, e: "🍿", t: "Das erste Autokino", x: "In Camden im US-Bundesstaat New Jersey eröffnete das erste Autokino. Der Erfinder Richard Hollingshead hatte zuvor in seinem Garten ausprobiert, wie man Autos in Reihen stellen muss, damit alle freie Sicht haben. Den Ton lieferten damals große Lautsprecher neben der Leinwand." },
  "06-07": { e: "🥗", t: "Tag der Lebensmittelsicherheit", x: "Heute ist Welttag der Lebensmittelsicherheit. Jedes Jahr erkranken weltweit Hunderte Millionen Menschen durch verdorbene oder verunreinigte Lebensmittel. Einfache Regeln helfen: Hände waschen, rohes Fleisch getrennt halten, gründlich durchgaren und Kühlschränke auf höchstens sieben Grad einstellen." },
  "06-08": { e: "🐋", t: "Tag der Ozeane", x: "Heute ist Welttag der Ozeane. Die Meere bedecken rund 71 Prozent der Erdoberfläche und liefern einen großen Teil des Sauerstoffs, den wir atmen – gebildet von winzigem Plankton. Sie nehmen außerdem viel Wärme und Kohlendioxid auf und bremsen so den Klimawandel." },
  "06-09": { y: 1934, e: "🦆", t: "Donald Duck hat seinen ersten Auftritt", x: "In dem Zeichentrickfilm „The Wise Little Hen“ trat Donald Duck zum ersten Mal auf – als faule Ente, die sich vor der Arbeit drückt. Mit seinem Matrosenanzug und seiner schwer verständlichen Stimme wurde er schnell zum Publikumsliebling. In Deutschland wurde er durch die Übersetzungen von Erika Fuchs besonders beliebt." },
  "06-10": { y: 2003, e: "🔴", t: "Der Rover Spirit startet", x: "Der Mars-Rover Spirit startete in Richtung Mars, einige Wochen später folgte sein Zwilling Opportunity. Geplant war ein Einsatz von 90 Marstagen. Spirit arbeitete über sechs Jahre, Opportunity sogar rund 15 Jahre. Ihre Funde zeigten, dass es auf dem Mars einst flüssiges Wasser gab." },
  "06-11": { y: 1910, e: "🤿", t: "Jacques Cousteau wird geboren", x: "Der französische Meeresforscher Jacques-Yves Cousteau entwickelte mit einem Ingenieur das Drucklufttauchgerät, mit dem Taucher sich frei unter Wasser bewegen können. Mit seinem Schiff Calypso und zahlreichen Filmen zeigte er Millionen Menschen die Wunder der Unterwasserwelt." },
  "06-12": { y: 1827, e: "🏔️", t: "Johanna Spyri wird geboren", x: "Die Schweizer Schriftstellerin Johanna Spyri schrieb „Heidi“, die Geschichte eines Waisenmädchens, das bei seinem Großvater auf der Alm lebt. Das Buch wurde in rund 50 Sprachen übersetzt und oft verfilmt. In Japan entstand daraus eine Zeichentrickserie, die auch in Deutschland Generationen prägte." },
  "06-13": { y: 1983, e: "🛸", t: "Pioneer 10 verlässt die Planeten", x: "Die Raumsonde Pioneer 10 überquerte als erstes von Menschen gebautes Objekt die Bahn des äußersten Planeten Neptun. An Bord trägt sie eine Plakette mit einer Zeichnung eines Mannes und einer Frau und der Position der Erde – eine Botschaft an mögliche Außerirdische." },
  "06-14": { y: 1868, e: "🩸", t: "Weltblutspendetag", x: "Am 14. Juni 1868 wurde der Wiener Arzt Karl Landsteiner geboren. Er entdeckte die Blutgruppen A, B und 0 und machte damit sichere Bluttransfusionen möglich. Zu seinen Ehren ist heute Weltblutspendetag. Eine einzige Blutspende kann bis zu drei Menschen helfen." },
  "06-15": { e: "🌬️", t: "Tag des Windes", x: "Heute ist Tag des Windes. Wind entsteht, weil die Sonne die Erde ungleichmäßig erwärmt: Warme Luft steigt auf, kühlere strömt nach. In Deutschland ist Windkraft inzwischen die wichtigste Stromquelle. Die stärkste je gemessene Windböe erreichte über 400 Kilometer pro Stunde während eines Zyklons in Australien." },
  "06-16": { y: 1963, e: "👩‍🚀", t: "Die erste Frau im All", x: "Die sowjetische Kosmonautin Valentina Tereschkowa flog als erste Frau ins All. Sie umkreiste die Erde fast drei Tage lang 48-mal und war damit länger im All als alle amerikanischen Astronauten bis dahin zusammen. Zuvor hatte sie in einer Textilfabrik gearbeitet und war Fallschirmspringerin." },
  "06-17": { e: "🏜️", t: "Tag gegen Wüstenbildung", x: "Heute ist Welttag zur Bekämpfung von Wüstenbildung und Dürre. Wenn Böden durch Übernutzung, Abholzung und Trockenheit ihre Fruchtbarkeit verlieren, breiten sich Wüsten aus. In Afrika entsteht deshalb eine Grüne Mauer aus Bäumen und Hecken quer durch die Sahelzone." },
  "06-18": { e: "🧺", t: "Tag des Picknicks", x: "Heute ist Internationaler Picknicktag. Das Wort Picknick stammt vermutlich aus dem Französischen, wo pique-nique ein Essen bezeichnete, zu dem jeder etwas mitbringt. Im 19. Jahrhundert wurde das Essen im Grünen in Europa zur beliebten Freizeitbeschäftigung, als Parks für alle zugänglich wurden." },
  "06-19": { y: 1623, e: "🧮", t: "Blaise Pascal wird geboren", x: "Der französische Mathematiker Blaise Pascal baute als Teenager eine der ersten Rechenmaschinen, um seinem Vater bei Steuerberechnungen zu helfen. Er erforschte den Luftdruck und begründete mit anderen die Wahrscheinlichkeitsrechnung. Die Einheit des Drucks, das Pascal, trägt seinen Namen." },
  "06-20": { y: 1819, e: "🎭", t: "Jacques Offenbach wird geboren", x: "Der in Köln geborene Komponist Jacques Offenbach ging als Jugendlicher nach Paris und wurde dort mit heiteren Operetten berühmt. Sein Galopp aus „Orpheus in der Unterwelt“ ist heute als Musik zum Can-Can weltbekannt. Sein letztes Werk „Hoffmanns Erzählungen“ gehört zu den meistgespielten Opern." },
  "06-21": { e: "☀️", t: "Sommeranfang", x: "Um den 21. Juni steht die Sonne mittags so hoch wie im ganzen Jahr nicht, und es ist der längste Tag des Jahres. In Norddeutschland wird es kaum richtig dunkel. Nördlich des Polarkreises geht die Sonne gar nicht unter. Heute ist außerdem Fête de la Musique mit Konzerten auf den Straßen." },
  "06-22": { y: 1978, e: "🌑", t: "Plutos Mond Charon", x: "Der Astronom James Christy bemerkte auf Fotoplatten, dass Pluto eine seltsame Beule hatte, die regelmäßig wanderte. Es war ein Mond: Charon. Er ist im Verhältnis zu Pluto so groß, dass beide um einen gemeinsamen Punkt zwischen sich kreisen. Man spricht deshalb manchmal von einem Doppelsystem." },
  "06-23": { y: 1912, e: "💻", t: "Alan Turing wird geboren", x: "Der britische Mathematiker Alan Turing beschrieb 1936 eine gedachte Rechenmaschine, die zum theoretischen Fundament aller Computer wurde. Er dachte früh darüber nach, ob Maschinen denken können, und schlug dafür einen Test vor. Heute ist er auf der britischen 50-Pfund-Note abgebildet." },
  "06-24": { e: "🥬", t: "Johannistag", x: "Heute ist Johannistag. Traditionell endet an diesem Tag die Spargelernte, damit sich die Pflanzen bis zum nächsten Jahr erholen können – man nennt ihn deshalb auch Spargelsilvester. Auch Rhabarber wird ab jetzt meist nicht mehr geerntet. Johannisbeeren sind nach diesem Tag benannt, weil sie um diese Zeit reif werden." },
  "06-25": { y: 1852, e: "⛪", t: "Antoni Gaudí wird geboren", x: "Der katalanische Architekt Antoni Gaudí baute in Barcelona fantasievolle Häuser mit geschwungenen Fassaden, bunten Mosaiken und kaum geraden Linien. Sein Hauptwerk, die Basilika Sagrada Família, ist seit über 140 Jahren im Bau. Gaudí orientierte sich an Formen aus der Natur, etwa Bäumen und Knochen." },
  "06-26": { y: 1997, e: "⚡", t: "Harry Potter erscheint", x: "In Großbritannien erschien „Harry Potter und der Stein der Weisen“ in einer kleinen Auflage von rund 500 gebundenen Exemplaren. Zuvor hatten mehrere Verlage das Manuskript abgelehnt. Die sieben Bände verkauften sich später über 500 Millionen Mal und wurden in rund 80 Sprachen übersetzt." },
  "06-27": { y: 1967, e: "🏧", t: "Der erste Geldautomat", x: "Im Londoner Stadtteil Enfield wurde der erste Geldautomat in Betrieb genommen. Statt Karten benutzte man damals mit einem leicht radioaktiven Stoff markierte Schecks. Die Idee zur Geheimzahl hatte der Erfinder John Shepherd-Barron; er wählte vier Ziffern, weil seine Frau sich nicht mehr merken konnte." },
  "06-28": { y: 1577, e: "🖼️", t: "Peter Paul Rubens wird geboren", x: "Der flämische Maler Peter Paul Rubens wurde im westfälischen Siegen geboren. Er malte prächtige, bewegte Barockgemälde mit vielen Figuren und betrieb eine große Werkstatt mit Gehilfen. Weil er gern üppige Frauenkörper malte, spricht man bis heute von rubensschen Formen." },
  "06-29": { y: 1900, e: "🌹", t: "Antoine de Saint-Exupéry wird geboren", x: "Der französische Schriftsteller und Pilot Antoine de Saint-Exupéry schrieb „Der kleine Prinz“, eines der meistübersetzten Bücher der Welt. Die Geschichte eines Piloten, der in der Wüste einem kleinen Prinzen von einem fernen Asteroiden begegnet, beruht auch auf einer echten Notlandung in der Sahara." },
  "06-30": { y: 1908, e: "☄️", t: "Asteroidentag", x: "Über der sibirischen Tunguska explodierte ein Objekt aus dem All in mehreren Kilometern Höhe. Die Druckwelle knickte rund 80 Millionen Bäume auf einer Fläche größer als Berlin um. Zur Erinnerung ist heute Asteroidentag, der auf die Gefahr durch Einschläge aufmerksam macht." },
  "07-01": { y: 1858, e: "🐒", t: "Die Evolutionstheorie wird vorgestellt", x: "In London wurden bei einer Sitzung der Linné-Gesellschaft Schriften von Charles Darwin und Alfred Russel Wallace verlesen, die unabhängig voneinander die natürliche Auslese beschrieben. Beide waren nicht anwesend. Der Präsident der Gesellschaft meinte später, das Jahr habe keine bahnbrechenden Entdeckungen gebracht." },
  "07-02": { y: 1900, e: "🎈", t: "Der erste Zeppelin fliegt", x: "Über dem Bodensee bei Friedrichshafen stieg das Luftschiff LZ 1 zu seinem ersten Flug auf. Graf Ferdinand von Zeppelin hatte das 128 Meter lange Luftschiff mit einem Gerippe aus Aluminium gebaut. Der Flug dauerte nur 18 Minuten, doch Zeppeline wurden später zu einem Symbol der Luftfahrt." },
  "07-03": { y: 1883, e: "🪳", t: "Franz Kafka wird geboren", x: "Der Prager Schriftsteller Franz Kafka arbeitete tagsüber bei einer Versicherung und schrieb nachts. In seiner Erzählung „Die Verwandlung“ erwacht ein Mann als riesiges Insekt. Kafka wollte seine Manuskripte verbrennen lassen, doch sein Freund Max Brod veröffentlichte sie. Das Wort kafkaesk steht heute für Bedrückend-Rätselhaftes." },
  "07-04": { y: 2012, e: "⚛️", t: "Das Higgs-Teilchen", x: "Am Forschungszentrum CERN gaben Physiker bekannt, dass sie ein neues Teilchen gefunden hatten: das Higgs-Boson. Es war fast 50 Jahre zuvor vorhergesagt worden und erklärt, warum Elementarteilchen eine Masse haben. Peter Higgs, der es vorhergesagt hatte, verfolgte die Verkündung mit Tränen in den Augen." },
  "07-05": { y: 1996, e: "🐑", t: "Das Schaf Dolly", x: "In Schottland kam das Schaf Dolly zur Welt, das erste Säugetier, das aus einer Körperzelle eines erwachsenen Tieres geklont wurde. Die Zelle stammte aus einem Euter; deshalb benannten die Forscher Dolly scherzhaft nach der Sängerin Dolly Parton. Dolly bekam später selbst sechs Lämmer." },
  "07-06": { y: 1885, e: "🐕", t: "Impfung gegen Tollwut", x: "Louis Pasteur behandelte in Paris den neunjährigen Joseph Meister, der von einem tollwütigen Hund gebissen worden war, mit einem neu entwickelten Impfstoff. Der Junge überlebte. Tollwut ist für Menschen fast immer tödlich, wenn Symptome einmal auftreten – durch rechtzeitige Impfung lässt sie sich aber verhindern." },
  "07-07": { e: "🍫", t: "Welttag der Schokolade", x: "Heute ist Welttag der Schokolade. Kakao stammt aus Mittel- und Südamerika, wo man ihn als bitteres Getränk trank. Erst in Europa wurde er mit Zucker gesüßt. Die meisten Kakaobohnen wachsen heute in Westafrika. Deutschland gehört zu den Ländern mit dem höchsten Schokoladenverbrauch pro Kopf." },
  "07-08": { y: 1621, e: "🦊", t: "Jean de La Fontaine wird geboren", x: "Der französische Dichter Jean de La Fontaine schrieb berühmte Fabeln, in denen Tiere menschliche Schwächen zeigen, etwa den Raben und den Fuchs oder die Grille und die Ameise. Viele Stoffe übernahm er vom antiken Dichter Äsop. Seine Fabeln lernen französische Kinder bis heute in der Schule." },
  "07-09": { y: 1979, e: "🪐", t: "Voyager 2 an Jupiter", x: "Die Raumsonde Voyager 2 flog am Jupiter vorbei und schickte Bilder seiner Wolkenwirbel und Monde zur Erde. Sie zeigten unter anderem Vulkane auf dem Mond Io. Voyager 2 besuchte später als einzige Sonde auch Uranus und Neptun und fliegt heute durch den interstellaren Raum." },
  "07-10": { y: 1856, e: "⚡", t: "Nikola Tesla wird geboren", x: "Der im heutigen Kroatien geborene Erfinder Nikola Tesla entwickelte den Wechselstrommotor und trug wesentlich zum Siegeszug des Wechselstroms bei. Er experimentierte mit drahtloser Energieübertragung und riesigen Blitzen. Die Einheit der magnetischen Flussdichte heißt ihm zu Ehren Tesla." },
  "07-11": { e: "👥", t: "Weltbevölkerungstag", x: "Heute ist Weltbevölkerungstag. Über acht Milliarden Menschen leben auf der Erde. Um 1800 war es erst rund eine Milliarde. Das Wachstum verlangsamt sich inzwischen, weil Familien in vielen Ländern kleiner werden. Fachleute erwarten, dass die Weltbevölkerung in diesem Jahrhundert ihren Höchststand erreicht." },
  "07-12": { y: 2022, e: "🔭", t: "Die ersten Webb-Bilder", x: "Die ersten farbigen Bilder des James-Webb-Weltraumteleskops wurden veröffentlicht. Sie zeigten Galaxien, deren Licht über 13 Milliarden Jahre unterwegs war, und leuchtende Sternentstehungsgebiete in nie gesehener Schärfe. Webb beobachtet im Infrarotlicht und blickt so durch Staubwolken hindurch." },
  "07-13": { y: 1985, e: "🎤", t: "Live Aid", x: "In London und Philadelphia fanden gleichzeitig zwei riesige Benefizkonzerte für die Opfer einer Hungersnot in Äthiopien statt, mit Stars wie Queen, David Bowie und U2. Die Konzerte wurden weltweit im Fernsehen übertragen und von schätzungsweise über einer Milliarde Menschen gesehen." },
  "07-14": { y: 2015, e: "🤍", t: "Vorbeiflug an Pluto", x: "Die Raumsonde New Horizons raste nach neun Jahren Flug an Pluto vorbei und lieferte die ersten scharfen Bilder des Zwergplaneten. Sie zeigten Eisberge, Gletscher aus gefrorenem Stickstoff und eine riesige herzförmige Ebene. An Bord flog ein wenig Asche von Clyde Tombaugh, der Pluto entdeckt hatte." },
  "07-15": { y: 1606, e: "🖌️", t: "Rembrandt wird geboren", x: "Der niederländische Maler Rembrandt van Rijn war ein Meister von Licht und Schatten. Sein riesiges Gemälde „Die Nachtwache“ zeigt eine Gruppe von Schützen in dramatischem Licht. Er malte sich selbst fast hundertmal und hielt dabei ehrlich fest, wie er alterte." },
  "07-16": { e: "🐍", t: "Tag der Schlange", x: "Heute ist Welttag der Schlange. Schlangen haben keine Ohrmuscheln, spüren aber Erschütterungen über den Unterkiefer. Sie riechen mit der gespaltenen Zunge. In Deutschland leben nur wenige Arten, darunter die harmlose Ringelnatter und die scheue, giftige Kreuzotter." },
  "07-17": { y: 1955, e: "🏰", t: "Disneyland öffnet", x: "In Anaheim in Kalifornien eröffnete Walt Disney seinen ersten Themenpark. Am Eröffnungstag lief vieles schief: Es kamen weit mehr Besucher als geplant, der frische Asphalt war so weich, dass Schuhe steckenblieben, und Trinkbrunnen fehlten. Trotzdem wurde Disneyland ein riesiger Erfolg." },
  "07-18": { y: 1968, e: "🔲", t: "Intel wird gegründet", x: "Die Ingenieure Robert Noyce und Gordon Moore gründeten in Kalifornien die Firma Intel. Drei Jahre später brachte sie den ersten Mikroprozessor auf den Markt. Moore hatte zuvor vorhergesagt, dass sich die Zahl der Transistoren auf einem Chip regelmäßig verdoppeln würde – das Mooresche Gesetz." },
  "07-19": { y: 1834, e: "🩰", t: "Edgar Degas wird geboren", x: "Der französische Maler Edgar Degas ist vor allem für seine Bilder von Balletttänzerinnen bekannt, die er bei Proben und hinter den Kulissen zeigte. Er malte mit Pastellkreide und formte auch Skulpturen. Seine Statue einer jungen Tänzerin trug einen echten Rock aus Stoff." },
  "07-20": { y: 1969, e: "🌕", t: "Die Mondlandung", x: "Die Mondfähre von Apollo 11 setzte im Meer der Ruhe auf dem Mond auf. Wenige Stunden später betrat Neil Armstrong als erster Mensch den Mond. Rund 600 Millionen Menschen verfolgten die Bilder live im Fernsehen. Die Fußabdrücke sind noch heute dort, denn auf dem Mond gibt es keinen Wind." },
  "07-21": { y: 1899, e: "🎣", t: "Ernest Hemingway wird geboren", x: "Der amerikanische Schriftsteller Ernest Hemingway schrieb in knappen, klaren Sätzen. In seiner Erzählung „Der alte Mann und das Meer“ kämpft ein kubanischer Fischer tagelang mit einem riesigen Marlin. Hemingway erhielt 1954 den Literaturnobelpreis." },
  "07-22": { e: "🥧", t: "Tag der Pi-Näherung", x: "Heute ist Tag der Pi-Näherung, denn 22 geteilt durch 7 ergibt ungefähr 3,14. Schon der griechische Mathematiker Archimedes zeigte, dass Pi zwischen 3 10/71 und 3 1/7 liegen muss. Der Bruch 22/7 ist eine praktische Näherung, die bis auf wenige Tausendstel genau ist." },
  "07-23": { y: 1999, e: "🛰️", t: "Das Röntgenteleskop Chandra", x: "Das Space Shuttle Columbia brachte das Röntgenteleskop Chandra ins All, damals unter dem Kommando von Eileen Collins, der ersten Frau als Kommandantin eines Shuttles. Chandra beobachtet heißes Gas um Schwarze Löcher und Überreste explodierter Sterne, die in Röntgenlicht leuchten." },
  "07-24": { y: 1897, e: "🛩️", t: "Amelia Earhart wird geboren", x: "Die amerikanische Pilotin Amelia Earhart überquerte 1932 als erste Frau allein den Atlantik im Flugzeug. Sie setzte sich dafür ein, dass Frauen fliegen und Berufe frei wählen können. Bei einem Versuch, die Erde zu umrunden, verschwand sie 1937 über dem Pazifik." },
  "07-25": { y: 1978, e: "👶", t: "Das erste Retortenbaby", x: "In England kam Louise Brown zur Welt, der erste Mensch, der durch künstliche Befruchtung außerhalb des Körpers entstanden war. Die Ärzte hatten Ei- und Samenzelle in einer Laborschale zusammengebracht. Seitdem sind weltweit über zehn Millionen Kinder auf diese Weise geboren worden." },
  "07-26": { y: 1887, e: "💚", t: "Esperanto entsteht", x: "Der Augenarzt Ludwik Zamenhof veröffentlichte in Warschau ein Lehrbuch für eine neue Sprache, die jeder leicht lernen können sollte: Esperanto, was so viel heißt wie der Hoffende. Die Grammatik kommt ohne Ausnahmen aus. Heute sprechen weltweit schätzungsweise einige Zehntausend bis Hunderttausende Menschen Esperanto." },
  "07-27": { y: 1940, e: "🥕", t: "Bugs Bunny hat seinen ersten Auftritt", x: "Im Zeichentrickfilm „A Wild Hare“ fragte ein Hase erstmals lässig an einer Karotte kauend: Was gibt’s Neues, Doc? Bugs Bunny wurde zu einer der bekanntesten Zeichentrickfiguren der Welt. 1985 erhielt er als eine der ersten Zeichentrickfiguren einen Stern auf dem Walk of Fame in Hollywood." },
  "07-28": { y: 1866, e: "🐰", t: "Beatrix Potter wird geboren", x: "Die englische Autorin Beatrix Potter schrieb und illustrierte Geschichten um Peter Hase. Sie war auch eine begabte Naturforscherin und zeichnete Pilze so genau, dass ihre Bilder noch heute geschätzt werden. Mit ihren Einnahmen kaufte sie Bauernhöfe und Land im Lake District und schützte es vor Bebauung." },
  "07-29": { e: "🐅", t: "Welttigertag", x: "Heute ist Welttigertag. Tiger sind die größten Katzen der Erde. In freier Wildbahn leben nur noch einige Tausend, die meisten in Indien. Kein Tiger gleicht dem anderen: Das Streifenmuster ist so einzigartig wie ein Fingerabdruck. Forscher erkennen einzelne Tiere auf Fotos von Kamerafallen daran." },
  "07-30": { y: 1863, e: "🏭", t: "Henry Ford wird geboren", x: "Der amerikanische Unternehmer Henry Ford machte das Auto für viele erschwinglich, indem er es am Fließband produzieren ließ. Die Montagezeit eines Ford Modell T sank von über zwölf Stunden auf rund anderthalb. Das Modell T gab es lange Zeit nur in Schwarz, weil diese Farbe am schnellsten trocknete." },
  "07-31": { e: "🦺", t: "Welt-Ranger-Tag", x: "Heute ist Welt-Ranger-Tag. Ranger schützen Nationalparks und Naturschutzgebiete, zählen Tiere, betreuen Besucher und gehen gegen Wilderer vor. Ihr Beruf ist mancherorts gefährlich. In Deutschland arbeiten Ranger etwa im Nationalpark Bayerischer Wald oder im Wattenmeer." },
  "08-01": { y: 1774, e: "🫁", t: "Sauerstoff wird entdeckt", x: "Der englische Naturforscher Joseph Priestley erhitzte Quecksilberoxid mit einem Brennglas und fing das entstehende Gas auf. Eine Kerze brannte darin besonders hell, und eine Maus blieb darin länger lebendig als in normaler Luft. Er hatte Sauerstoff entdeckt – unabhängig vom Schweden Carl Wilhelm Scheele." },
  "08-02": { y: 1932, e: "⚛️", t: "Antimaterie entdeckt", x: "Der amerikanische Physiker Carl Anderson entdeckte in Aufnahmen von kosmischer Strahlung ein Teilchen, das sich wie ein Elektron verhielt, aber positiv geladen war: das Positron, das erste nachgewiesene Antimaterieteilchen. Heute nutzt man Positronen in der Medizin, etwa bei der Positronen-Emissions-Tomografie." },
  "08-03": { y: 1958, e: "🧊", t: "Unter dem Nordpol hindurch", x: "Das amerikanische Atom-U-Boot Nautilus durchquerte den Nordpol unter dem Eis. Es war das erste Schiff, das den geografischen Nordpol erreichte. Die Besatzung navigierte fast blind, denn Kompasse sind nahe dem Pol unzuverlässig. Der Name stammt vom U-Boot aus Jules Vernes Roman." },
  "08-04": { y: 1693, e: "🥂", t: "Sterne im Glas", x: "Der Legende nach soll der Mönch Dom Pérignon an diesem Tag in der Champagne zum ersten Mal Schaumwein gekostet und gerufen haben: Kommt schnell, ich trinke Sterne! Tatsächlich versuchte er eher, die Bläschen im Wein zu verhindern. Die Geschichte wurde vermutlich viel später erfunden." },
  "08-05": { y: 1888, e: "🛣️", t: "Bertha Benz fährt los", x: "Bertha Benz fuhr mit ihren zwei Söhnen im Motorwagen ihres Mannes Carl von Mannheim nach Pforzheim, rund 100 Kilometer – die erste Überlandfahrt mit einem Automobil. Unterwegs kaufte sie Benzin in einer Apotheke und reinigte eine verstopfte Leitung mit ihrer Hutnadel." },
  "08-06": { y: 2012, e: "🔴", t: "Curiosity landet auf dem Mars", x: "Der Rover Curiosity, so groß wie ein Kleinwagen, landete auf dem Mars. Dafür wurde er in den letzten Sekunden von einem schwebenden Raketengestell an Seilen herabgelassen – ein Manöver, das man die sieben Minuten des Schreckens nannte. Curiosity fand Hinweise, dass auf dem Mars einst lebensfreundliche Bedingungen herrschten." },
  "08-07": { y: 1959, e: "🌍", t: "Das erste Bild der Erde aus der Umlaufbahn", x: "Der amerikanische Satellit Explorer 6 startete ins All und schickte wenige Tage später das erste Foto der Erde aus einer Umlaufbahn. Das grobkörnige Bild zeigte einen sonnenbeschienenen Teil des Pazifiks mit Wolken. Heute umkreisen Tausende Satelliten die Erde und fotografieren sie ständig." },
  "08-08": { e: "🐱", t: "Weltkatzentag", x: "Heute ist Internationaler Tag der Katze. Katzen verbringen rund zwei Drittel des Tages mit Schlafen und Dösen. Ihr Schnurren entsteht durch schnelle Bewegungen der Kehlkopfmuskeln. Forscher vermuten, dass die Schwingungen auch helfen könnten, Knochen und Gewebe zu heilen." },
  "08-09": { y: 1914, e: "🦛", t: "Tove Jansson wird geboren", x: "Die finnische Künstlerin Tove Jansson erfand die Mumins, freundliche Trollwesen, die an Nilpferde erinnern und im Mumintal leben. Ihre Bücher und Comics wurden in viele Sprachen übersetzt. Jansson war zugleich Malerin und lebte viele Sommer auf einer winzigen Insel im Finnischen Meerbusen." },
  "08-10": { e: "🦁", t: "Welttag des Löwen", x: "Heute ist Welttag des Löwen. Löwen sind die einzigen Katzen, die in Rudeln leben. Die Jagd übernehmen meist die Weibchen. Das Brüllen eines Männchens ist bis zu acht Kilometer weit zu hören. In Afrika gibt es heute nur noch einen Bruchteil der Löwen von vor hundert Jahren." },
  "08-11": { y: 1999, e: "🌑", t: "Sonnenfinsternis über Deutschland", x: "Über Süddeutschland zog eine totale Sonnenfinsternis. Für rund zwei Minuten wurde es mitten am Tag dunkel, die Temperatur sank, Vögel verstummten. Millionen Menschen blickten mit Spezialbrillen in den Himmel, doch vielerorts verdarben Wolken die Sicht. Die nächste totale Finsternis in Deutschland gibt es erst 2081." },
  "08-12": { e: "🌠", t: "Sternschnuppennacht", x: "Um den 12. August erreichen die Perseiden ihren Höhepunkt, einer der schönsten Sternschnuppenströme des Jahres. Die Erde zieht dann durch eine Staubspur, die der Komet Swift-Tuttle hinterlassen hat. Die Staubkörnchen verglühen in der Atmosphäre. In dunklen Nächten sieht man manchmal Dutzende pro Stunde." },
  "08-13": { e: "✍️", t: "Tag der Linkshänder", x: "Heute ist Internationaler Tag der Linkshänder. Rund jeder zehnte Mensch ist Linkshänder. Früher wurden linkshändige Kinder oft gezwungen, mit rechts zu schreiben, was zu Problemen führen konnte. Heute gibt es spezielle Scheren, Füller und Dosenöffner für Linkshänder." },
  "08-14": { y: 1777, e: "🧭", t: "Hans Christian Ørsted wird geboren", x: "Der dänische Physiker Hans Christian Ørsted bemerkte während einer Vorlesung, dass eine Kompassnadel ausschlug, wenn in einem Draht daneben Strom floss. Damit bewies er, dass Elektrizität und Magnetismus zusammenhängen. Diese Entdeckung führte zu Elektromotoren und Generatoren." },
  "08-15": { y: 1969, e: "🎸", t: "Woodstock beginnt", x: "Auf einer Farm im US-Bundesstaat New York begann das Musikfestival Woodstock. Statt der erwarteten 50.000 kamen rund 400.000 Menschen. Trotz Regen, Schlamm und Lebensmittelknappheit blieb es weitgehend friedlich. Jimi Hendrix spielte zum Abschluss am Montagmorgen vor nur noch wenigen Zehntausend Zuhörern." },
  "08-16": { y: 1960, e: "🪂", t: "Sprung aus der Stratosphäre", x: "Der amerikanische Pilot Joseph Kittinger sprang aus einer Ballongondel in über 31 Kilometern Höhe. Im freien Fall erreichte er fast 1.000 Kilometer pro Stunde, bevor sich sein Fallschirm öffnete. Die Erfahrungen halfen bei der Entwicklung von Raumanzügen. Sein Rekord hielt über 50 Jahre." },
  "08-17": { y: 1807, e: "🚢", t: "Das Dampfschiff Clermont", x: "Robert Fultons Dampfschiff Clermont fuhr auf dem Hudson River von New York nach Albany. Für die rund 240 Kilometer brauchte es 32 Stunden, Segelschiffe benötigten oft Tage. Spötter hatten das Schiff Fultons Torheit genannt. Es war das erste wirtschaftlich erfolgreiche Dampfschiff." },
  "08-18": { y: 1868, e: "☀️", t: "Helium in der Sonne", x: "Während einer Sonnenfinsternis in Indien untersuchte der französische Astronom Jules Janssen das Licht der Sonne und fand eine unbekannte gelbe Spektrallinie. Sie stammte von einem neuen Element, das man nach dem griechischen Wort für Sonne Helium nannte. Auf der Erde wurde es erst 27 Jahre später nachgewiesen." },
  "08-19": { y: 1839, e: "📸", t: "Welttag der Fotografie", x: "In Paris wurde das Verfahren von Louis Daguerre öffentlich vorgestellt, mit dem man Bilder dauerhaft auf versilberten Kupferplatten festhalten konnte. Die französische Regierung kaufte die Rechte und gab die Erfindung der Welt frei. Die ersten Aufnahmen brauchten minutenlange Belichtung – Menschen mussten stillsitzen." },
  "08-20": { y: 1977, e: "🚀", t: "Voyager 2 startet", x: "Die Raumsonde Voyager 2 startete – übrigens vor ihrer Zwillingssonde Voyager 1. Eine seltene Stellung der Planeten erlaubte es, Jupiter, Saturn, Uranus und Neptun nacheinander zu besuchen. An Bord ist eine goldene Schallplatte mit Grüßen, Musik und Geräuschen der Erde." },
  "08-21": { y: 1911, e: "🖼️", t: "Die Mona Lisa wird gestohlen", x: "Aus dem Louvre in Paris verschwand die Mona Lisa. Der Dieb war ein italienischer Handwerker, der im Museum gearbeitet hatte und das Bild unter seinem Kittel hinaustrug. Erst über zwei Jahre später tauchte es in Florenz wieder auf. Durch den Diebstahl wurde das Gemälde erst richtig weltberühmt." },
  "08-22": { y: 1862, e: "🌙", t: "Claude Debussy wird geboren", x: "Der französische Komponist Claude Debussy schuf Musik, die wie Malerei mit Klangfarben wirkt. Sein Klavierstück „Clair de lune“ – Mondschein – gehört zu den bekanntesten Stücken der klassischen Musik. In „La Mer“ versuchte er, das Meer in Musik zu fassen." },
  "08-23": { y: 1966, e: "🌖", t: "Die Erde vom Mond aus", x: "Die Sonde Lunar Orbiter 1 fotografierte die Erde aus der Umlaufbahn um den Mond. Es war das erste Bild der Erde aus der Nähe des Mondes, noch in Schwarz-Weiß und grobkörnig. Zwei Jahre später machten Apollo-Astronauten das berühmte farbige Bild vom Erdaufgang." },
  "08-24": { y: 2006, e: "🧊", t: "Pluto wird Zwergplanet", x: "Die Internationale Astronomische Union legte in Prag erstmals fest, was ein Planet ist. Pluto erfüllte ein Kriterium nicht: Er hat seine Umlaufbahn nicht von anderen Himmelskörpern freigeräumt. Seitdem gilt er als Zwergplanet, und das Sonnensystem hat offiziell acht Planeten." },
  "08-25": { y: 2012, e: "🌌", t: "Voyager 1 verlässt die Sonnenblase", x: "Die Raumsonde Voyager 1 überquerte als erstes von Menschen gebautes Objekt die Grenze der Heliosphäre, also des Bereichs, den der Sonnenwind prägt. Seitdem fliegt sie durch den interstellaren Raum. Ihre Funksignale brauchen inzwischen fast einen ganzen Tag bis zur Erde." },
  "08-26": { y: 1743, e: "⚗️", t: "Antoine Lavoisier wird geboren", x: "Der französische Chemiker Antoine Lavoisier zeigte durch genaues Wiegen, dass bei chemischen Reaktionen keine Masse verloren geht. Er erklärte die Verbrennung als Verbindung mit Sauerstoff und gab dem Element seinen Namen. Unterstützt wurde er von seiner Frau Marie-Anne, die seine Experimente zeichnete." },
  "08-27": { y: 1859, e: "🛢️", t: "Die erste Ölbohrung", x: "In Titusville in Pennsylvania stieß Edwin Drake mit einer Bohrung in rund 21 Metern Tiefe auf Erdöl. Es war eine der ersten gezielten Ölbohrungen der Welt. Zunächst nutzte man das Öl vor allem für Lampen. Mit dem Auto wurde es später zum wichtigsten Energieträger." },
  "08-28": { y: 1749, e: "✒️", t: "Goethe wird geboren", x: "In Frankfurt am Main kam Johann Wolfgang von Goethe zur Welt, der wohl bekannteste deutsche Dichter. Er schrieb den „Faust“ und den „Werther“, forschte aber auch zu Pflanzen, Farben und Knochen. Er entdeckte beim Menschen den Zwischenkieferknochen, den man nur bei Tieren kannte." },
  "08-29": { y: 1831, e: "🧲", t: "Die elektromagnetische Induktion", x: "Michael Faraday wickelte zwei Drahtspulen um einen Eisenring und bemerkte, dass beim Ein- und Ausschalten des Stroms in der einen Spule auch in der anderen kurz Strom floss. Er hatte die elektromagnetische Induktion entdeckt. Nach diesem Prinzip erzeugen Generatoren in Kraftwerken bis heute Strom." },
  "08-30": { y: 1797, e: "🧟", t: "Mary Shelley wird geboren", x: "Die englische Schriftstellerin Mary Shelley schrieb mit nur 18 Jahren „Frankenstein“, in dem ein Forscher aus Leichenteilen ein Wesen erschafft. Die Idee entstand in einem verregneten Sommer am Genfer See bei einem Wettbewerb um die beste Gruselgeschichte. Der Roman gilt als einer der ersten Science-Fiction-Romane." },
  "08-31": { y: 1870, e: "🧩", t: "Maria Montessori wird geboren", x: "Die Italienerin Maria Montessori war eine der ersten Ärztinnen ihres Landes. Sie entwickelte eine Pädagogik, bei der Kinder mit speziellen Materialien selbstständig lernen. Ihr Leitsatz lautete: Hilf mir, es selbst zu tun. Weltweit gibt es heute Zehntausende Montessori-Kindergärten und -Schulen." },
  "09-01": { e: "🍂", t: "Meteorologischer Herbstanfang", x: "Heute beginnt für Wetterdienste der Herbst. Die Tage werden merklich kürzer, und in klaren Nächten bildet sich morgens Tau oder Nebel. Viele Zugvögel wie Schwalben und Störche sind bereits auf dem Weg nach Süden. Der kalendarische Herbst beginnt erst um den 22. September." },
  "09-02": { e: "🥥", t: "Welttag der Kokosnuss", x: "Heute ist Welttag der Kokosnuss. Die Kokosnuss ist botanisch keine Nuss, sondern eine Steinfrucht. Sie kann wochenlang im Meer treiben und an fernen Stränden keimen – so verbreitete sich die Kokospalme über die Tropen. Aus Kokosnüssen gewinnt man Wasser, Milch, Öl, Fasern und Holzkohle." },
  "09-03": { y: 1976, e: "🔴", t: "Viking 2 landet auf dem Mars", x: "Die amerikanische Sonde Viking 2 landete auf dem Mars, wenige Wochen nach ihrer Zwillingssonde Viking 1. Beide suchten mit Experimenten nach Spuren von Leben im Marsboden. Die Ergebnisse waren rätselhaft und werden bis heute diskutiert. Viking 2 fotografierte sogar Reif auf der Marsoberfläche." },
  "09-04": { y: 1998, e: "🔎", t: "Google wird gegründet", x: "Die Studenten Larry Page und Sergey Brin gründeten in Kalifornien die Firma Google, zunächst in einer Garage. Ihre Suchmaschine bewertete Webseiten danach, wie viele andere Seiten auf sie verlinkten. Der Name stammt von Googol, einer Zahl mit hundert Nullen." },
  "09-05": { y: 1946, e: "🎤", t: "Freddie Mercury wird geboren", x: "Der Sänger Freddie Mercury wurde auf der Insel Sansibar geboren und wuchs teilweise in Indien auf. Als Frontmann der Band Queen wurde er mit einer Stimme von großem Umfang und legendären Auftritten weltberühmt. Den Song „Bohemian Rhapsody“ hielten viele für zu lang fürs Radio – er wurde ein Welthit." },
  "09-06": { y: 1766, e: "🔴", t: "John Dalton wird geboren", x: "Der englische Naturforscher John Dalton entwickelte die Vorstellung, dass jedes chemische Element aus eigenen, unteilbaren Atomen besteht. Er war außerdem selbst farbenblind und beschrieb diese Sehschwäche als Erster wissenschaftlich. Rot-Grün-Blindheit hieß deshalb lange Daltonismus." },
  "09-07": { e: "🌬️", t: "Tag der sauberen Luft", x: "Heute ist Internationaler Tag der sauberen Luft für blauen Himmel. Luftverschmutzung durch Feinstaub und Abgase gehört weltweit zu den größten Gesundheitsrisiken. In vielen deutschen Städten ist die Luft in den letzten Jahrzehnten deutlich sauberer geworden, etwa durch Filter in Kraftwerken und Autos." },
  "09-08": { e: "📖", t: "Weltalphabetisierungstag", x: "Heute ist Weltalphabetisierungstag. Weltweit können noch immer Hunderte Millionen Erwachsene nicht richtig lesen und schreiben, die meisten davon Frauen. Auch in Deutschland haben Millionen Erwachsene Schwierigkeiten mit dem Lesen längerer Texte. Es ist nie zu spät, es zu lernen – Volkshochschulen bieten Kurse an." },
  "09-09": { y: 1947, e: "🐛", t: "Der erste echte Computerbug", x: "Techniker der Harvard-Universität fanden in einem Relais ihres Computers Mark II eine Motte, die einen Fehler verursacht hatte. Sie klebten das Insekt ins Logbuch mit dem Vermerk: erster tatsächlich gefundener Bug. Das Wort Bug für technische Fehler war allerdings schon vorher gebräuchlich." },
  "09-10": { y: 2008, e: "🌀", t: "Der Teilchenbeschleuniger LHC startet", x: "Am CERN bei Genf kreiste zum ersten Mal ein Protonenstrahl durch den Large Hadron Collider, einen ringförmigen Tunnel von 27 Kilometern Umfang. In ihm werden Teilchen fast auf Lichtgeschwindigkeit beschleunigt und zusammengestoßen. Einige Menschen fürchteten, er könne ein Schwarzes Loch erzeugen – völlig unbegründet." },
  "09-11": { y: 1816, e: "🔍", t: "Carl Zeiss wird geboren", x: "Der Weimarer Mechaniker Carl Zeiss gründete in Jena eine Werkstatt für Mikroskope. Gemeinsam mit dem Physiker Ernst Abbe berechnete er Linsen erstmals wissenschaftlich statt durch Ausprobieren. Zeiss-Optiken stecken heute in Brillen, Kameras, Planetarien und Maschinen zur Chipherstellung." },
  "09-12": { y: 1940, e: "🐂", t: "Die Höhle von Lascaux", x: "Vier Jugendliche folgten in Südwestfrankreich ihrem Hund, der in ein Loch gefallen war, und entdeckten eine Höhle voller Wandmalereien: Pferde, Hirsche, Stiere, rund 17.000 Jahre alt. Weil die Atemluft der Besucher die Bilder schädigte, wurde die Höhle geschlossen. Heute besichtigt man originalgetreue Nachbauten." },
  "09-13": { y: 1916, e: "🍫", t: "Roald Dahl wird geboren", x: "Der britische Schriftsteller Roald Dahl schrieb Kinderbücher wie „Charlie und die Schokoladenfabrik“, „Matilda“ und „Sophiechen und der Riese“. Als Schüler durfte er Schokolade für einen Hersteller testen – das inspirierte ihn später. Sein Geburtstag wird in Großbritannien als Roald-Dahl-Tag gefeiert." },
  "09-14": { y: 1769, e: "🌋", t: "Alexander von Humboldt wird geboren", x: "Der Berliner Naturforscher Alexander von Humboldt erforschte fünf Jahre lang Südamerika, bestieg Vulkane und maß alles, was er fand. Er erkannte, dass in der Natur alles zusammenhängt. Nach ihm sind mehr Tiere, Pflanzen und Orte benannt als nach fast jedem anderen Menschen, sogar eine Meeresströmung." },
  "09-15": { y: 1890, e: "🕵️", t: "Agatha Christie wird geboren", x: "Die englische Autorin Agatha Christie schrieb über 60 Kriminalromane mit Detektiven wie Hercule Poirot und Miss Marple. Sie gehört zu den meistverkauften Autoren der Welt. Im Ersten Weltkrieg arbeitete sie in einer Apotheke – ihr Wissen über Gifte nutzte sie später in vielen Romanen." },
  "09-16": { e: "🛡️", t: "Tag der Ozonschicht", x: "Heute ist Internationaler Tag zum Schutz der Ozonschicht. Die Ozonschicht in der Stratosphäre filtert gefährliche UV-Strahlung. In den 1980er-Jahren entdeckte man ein Ozonloch über der Antarktis, verursacht durch FCKW aus Sprühdosen und Kühlschränken. Nach dem weltweiten Verbot erholt sich die Ozonschicht langsam." },
  "09-17": { y: 1991, e: "🐧", t: "Linux erscheint", x: "Der finnische Student Linus Torvalds veröffentlichte die erste Version seines Betriebssystemkerns Linux – nach eigenen Worten nur ein Hobby. Jeder durfte den Code frei nutzen und verbessern. Heute läuft Linux auf den meisten Servern im Internet, auf Supercomputern und in Android-Smartphones. Das Maskottchen ist der Pinguin Tux." },
  "09-18": { y: 1819, e: "🕰️", t: "Léon Foucault wird geboren", x: "Der französische Physiker Léon Foucault hängte 1851 im Pantheon in Paris ein schweres Pendel an einem langen Draht auf. Im Laufe der Stunden drehte sich die Schwingungsebene scheinbar – tatsächlich drehte sich die Erde darunter. So bewies er die Erdrotation ohne Blick zum Himmel." },
  "09-19": { y: 1991, e: "🏔️", t: "Ötzi wird gefunden", x: "Zwei Wanderer entdeckten in den Ötztaler Alpen an der Grenze zwischen Österreich und Italien eine im Eis erhaltene Leiche. Zunächst dachte man an einen verunglückten Bergsteiger – doch der Mann war rund 5.300 Jahre alt. Ötzi trug Kleidung, Werkzeuge und eine Kupferaxt bei sich." },
  "09-20": { e: "🧒", t: "Weltkindertag", x: "In Deutschland ist heute Weltkindertag, in Thüringen sogar ein Feiertag. Der Tag soll auf die Rechte und Bedürfnisse von Kindern aufmerksam machen: auf Bildung, Gesundheit, Schutz vor Gewalt und das Recht auf Spiel und Freizeit. In vielen Städten gibt es Feste und Aktionen für Kinder." },
  "09-21": { y: 1866, e: "👽", t: "H. G. Wells wird geboren", x: "Der englische Schriftsteller Herbert George Wells schrieb „Die Zeitmaschine“, „Der Krieg der Welten“ und „Der Unsichtbare“. Er gilt als einer der Väter der Science-Fiction. Viele seiner Ideen, etwa Reisen durch die Zeit oder Angriffe aus dem All, prägen Filme und Bücher bis heute." },
  "09-22": { y: 1791, e: "⚡", t: "Michael Faraday wird geboren", x: "Der Engländer Michael Faraday verließ die Schule früh und lernte als Buchbinderlehrling aus den Büchern, die er binden sollte. Später wurde er einer der bedeutendsten Experimentalphysiker. Er entdeckte die elektromagnetische Induktion und hielt berühmte Weihnachtsvorlesungen für Kinder." },
  "09-23": { y: 1846, e: "🔵", t: "Neptun wird entdeckt", x: "Der Astronom Johann Gottfried Galle entdeckte an der Berliner Sternwarte den Planeten Neptun – nur eine Stunde nach Beginn der Suche. Der Franzose Urbain Le Verrier hatte die Position vorausberechnet, weil die Bahn des Uranus kleine Unregelmäßigkeiten zeigte. Neptun wurde also zuerst auf dem Papier gefunden." },
  "09-24": { y: 1852, e: "🎈", t: "Das erste Luftschiff mit Motor", x: "Der französische Ingenieur Henri Giffard flog mit einem zigarrenförmigen, mit Gas gefüllten Luftschiff von Paris aus rund 27 Kilometer weit. Angetrieben wurde es von einer kleinen Dampfmaschine mit Propeller. Es war der erste motorisierte und lenkbare Flug der Geschichte, wenn auch nur bei schwachem Wind." },
  "09-25": { e: "💊", t: "Welttag der Apotheker", x: "Heute ist Welttag der Apothekerinnen und Apotheker. In Deutschland gibt es rund 17.000 Apotheken. Sie geben nicht nur Medikamente ab, sondern prüfen Wechselwirkungen, beraten und stellen selbst Arzneien her. Über Notdienste sind sie auch nachts und am Wochenende erreichbar." },
  "09-26": { e: "🗣️", t: "Europäischer Tag der Sprachen", x: "Heute ist Europäischer Tag der Sprachen. In Europa werden über 200 Sprachen gesprochen, darunter kleinere wie Sorbisch, Friesisch oder Rätoromanisch. Wer mehrere Sprachen lernt, trainiert sein Gehirn: Studien zeigen Vorteile beim Umschalten zwischen Aufgaben." },
  "09-27": { e: "🧳", t: "Welttourismustag", x: "Heute ist Welttourismustag. Vor der Corona-Pandemie wurden weltweit rund 1,5 Milliarden Auslandsreisen im Jahr gezählt. Tourismus bringt vielen Regionen Einkommen, kann aber auch Natur und Städte überlasten. Das beliebteste Reiseland der Deutschen ist seit Langem Spanien." },
  "09-28": { y: 1928, e: "🍄", t: "Penicillin wird entdeckt", x: "Der schottische Bakteriologe Alexander Fleming bemerkte nach dem Urlaub in seinem Labor, dass ein Schimmelpilz auf einer vergessenen Bakterienkultur die Bakterien ringsum abgetötet hatte. Er hatte das Penicillin entdeckt. Erst über zehn Jahre später wurde es als Medikament nutzbar gemacht." },
  "09-29": { y: 1954, e: "⚛️", t: "Das CERN wird gegründet", x: "Die Europäische Organisation für Kernforschung, kurz CERN, wurde bei Genf gegründet. Dort erforschen heute Tausende Wissenschaftler aus aller Welt die kleinsten Bausteine der Materie. Nebenbei entstand am CERN auch das World Wide Web." },
  "09-30": { e: "🌐", t: "Tag des Übersetzens", x: "Heute ist Internationaler Übersetzertag, am Gedenktag des Hieronymus, der die Bibel ins Lateinische übertrug. Übersetzer sorgen dafür, dass Bücher, Filme, Verträge und Gebrauchsanweisungen in anderen Sprachen verstanden werden. Ein gutes Übersetzen erfordert nicht nur Sprach-, sondern auch Kulturkenntnis." },
  "10-01": { e: "☕", t: "Tag des Kaffees", x: "Heute ist Internationaler Tag des Kaffees. Kaffee ist das beliebteste Getränk der Deutschen, noch vor Wasser und Bier. Die Pflanze stammt ursprünglich aus Äthiopien. Einer Legende nach bemerkte ein Hirte, dass seine Ziegen nach dem Fressen roter Beeren besonders munter herumsprangen." },
  "10-02": { y: 1950, e: "🐶", t: "Die Peanuts erscheinen", x: "In amerikanischen Zeitungen erschien der erste Comicstreifen der Peanuts von Charles M. Schulz. Charlie Brown, sein Hund Snoopy und ihre Freunde wurden zu Stars. Schulz zeichnete den Strip fast 50 Jahre lang allein, ohne Assistenten – insgesamt fast 18.000 Folgen." },
  "10-03": { y: 1985, e: "🚀", t: "Erstflug der Atlantis", x: "Das Space Shuttle Atlantis startete zu seinem ersten Flug. Es flog in den folgenden 26 Jahren über 30 Missionen, brachte Raumsonden auf den Weg und besuchte die Raumstationen Mir und ISS. 2011 beendete Atlantis mit dem letzten Flug das Shuttle-Programm und steht heute in einem Museum in Florida." },
  "10-04": { y: 1957, e: "🛰️", t: "Sputnik piept", x: "Die Sowjetunion brachte mit Sputnik 1 den ersten künstlichen Satelliten in eine Umlaufbahn um die Erde. Die glänzende Metallkugel war kaum größer als ein Wasserball und sendete ein einfaches Piepsignal, das Funkamateure weltweit empfangen konnten. Damit begann das Zeitalter der Raumfahrt." },
  "10-05": { e: "🍎", t: "Weltlehrertag", x: "Heute ist Weltlehrertag. Weltweit fehlen Millionen Lehrkräfte, besonders in Afrika südlich der Sahara. Studien zeigen, dass gute Lehrerinnen und Lehrer zu den wichtigsten Faktoren für den Lernerfolg gehören. In Deutschland unterrichten rund 800.000 Lehrkräfte an allgemeinbildenden Schulen." },
  "10-06": { y: 1995, e: "🌟", t: "Ein Planet bei einem anderen Stern", x: "Die Schweizer Astronomen Michel Mayor und Didier Queloz gaben die Entdeckung eines Planeten bekannt, der um einen sonnenähnlichen Stern kreist: 51 Pegasi b. Er ist ein heißer Gasriese, der seinen Stern in nur vier Tagen umrundet. Inzwischen kennt man über 5.000 solcher Exoplaneten." },
  "10-07": { y: 1885, e: "⚛️", t: "Niels Bohr wird geboren", x: "Der dänische Physiker Niels Bohr entwickelte ein Atommodell, in dem Elektronen auf bestimmten Bahnen um den Kern kreisen und beim Wechsel Licht aussenden. Er gehörte zu den Begründern der Quantenphysik und erhielt 1922 den Nobelpreis. Sein Institut in Kopenhagen war Treffpunkt der besten Physiker seiner Zeit." },
  "10-08": { e: "🐙", t: "Welt-Oktopus-Tag", x: "Heute ist Welt-Oktopus-Tag. Kraken haben drei Herzen, blaues Blut und neun Gehirne: eines im Kopf und je ein Nervenzentrum in jedem Arm. Sie können ihre Farbe blitzschnell wechseln, Gläser aufschrauben und aus Aquarien ausbrechen. Die meisten Arten leben nur ein bis zwei Jahre." },
  "10-09": { y: 1874, e: "✉️", t: "Weltposttag", x: "Am 9. Oktober 1874 wurde in Bern der Weltpostverein gegründet, damit Briefe über Ländergrenzen hinweg zu einheitlichen Regeln verschickt werden konnten. Zuvor musste man mit vielen Postverwaltungen einzeln abrechnen. Heute ist der Tag Weltposttag." },
  "10-10": { e: "💚", t: "Tag der seelischen Gesundheit", x: "Heute ist Welttag der seelischen Gesundheit. Fast jeder dritte Mensch erlebt im Laufe eines Jahres eine psychische Erkrankung, etwa Angststörungen oder Depressionen. Sie sind gut behandelbar. Wer Hilfe braucht, kann sich an den Hausarzt oder die Telefonseelsorge wenden, die rund um die Uhr erreichbar ist." },
  "10-11": { y: 1968, e: "📺", t: "Apollo 7 startet", x: "Mit Apollo 7 flogen erstmals drei amerikanische Astronauten gemeinsam ins All. Sie umkreisten elf Tage lang die Erde und testeten das neue Raumschiff für den Flug zum Mond. Von Bord sendeten sie die ersten Live-Fernsehbilder aus einem amerikanischen Raumschiff – mit Schildern voller Witze." },
  "10-12": { y: 1935, e: "🎙️", t: "Luciano Pavarotti wird geboren", x: "Der italienische Tenor Luciano Pavarotti machte Opernarien einem Millionenpublikum bekannt, etwa mit „Nessun dorma“ bei der Fußball-WM 1990. Mit den Drei Tenören füllte er Stadien. Er konnte übrigens kaum Noten lesen und lernte seine Partien vor allem nach Gehör." },
  "10-13": { y: 1884, e: "🌐", t: "Der Nullmeridian", x: "Auf einer internationalen Konferenz in Washington wurde beschlossen, den Längengrad durch die Sternwarte von Greenwich bei London zum Nullmeridian zu machen. Seitdem zählt man die geografische Länge von dort aus nach Osten und Westen. In Greenwich kann man heute mit einem Bein auf jeder Erdhälfte stehen." },
  "10-14": { y: 1947, e: "✈️", t: "Durch die Schallmauer", x: "Der amerikanische Testpilot Chuck Yeager flog mit dem Raketenflugzeug Bell X-1 als erster Mensch nachweislich schneller als der Schall. Viele hatten befürchtet, ein Flugzeug würde dabei zerbrechen. Yeager hatte sich kurz vorher zwei Rippen gebrochen und verschwieg das, um fliegen zu dürfen." },
  "10-15": { e: "🧼", t: "Welthändewaschtag", x: "Heute ist Welthändewaschtag. Gründliches Händewaschen mit Seife ist eine der wirksamsten Maßnahmen gegen Infektionen. Empfohlen werden 20 bis 30 Sekunden – etwa so lange, wie man zweimal Happy Birthday summt. Seife löst die Fetthülle vieler Viren und spült Keime von der Haut." },
  "10-16": { e: "🌾", t: "Welternährungstag", x: "Heute ist Welternährungstag, der Gründungstag der Welternährungsorganisation FAO. Weltweit werden genug Lebensmittel für alle erzeugt, dennoch hungern Hunderte Millionen Menschen. Gleichzeitig landet etwa ein Drittel aller Lebensmittel im Müll. In Deutschland wirft jeder Mensch im Schnitt rund 80 Kilogramm pro Jahr weg." },
  "10-17": { e: "🦩", t: "Die Kraniche ziehen", x: "Mitte Oktober ist Hochsaison für den Kranichzug. Zehntausende Kraniche rasten dann in Deutschland, etwa in Brandenburg und an der Ostseeküste, bevor sie nach Spanien und Nordafrika weiterziehen. Ihre trompetenden Rufe sind kilometerweit zu hören. Sie fliegen in charakteristischer Keilformation, die Energie spart." },
  "10-18": { y: 1922, e: "📻", t: "Die BBC wird gegründet", x: "In Großbritannien wurde die British Broadcasting Company gegründet, die spätere BBC. Wenige Wochen später sendete sie ihr erstes Programm. Die BBC wurde zu einem der einflussreichsten Sender der Welt und zum Vorbild für den öffentlich-rechtlichen Rundfunk in Deutschland." },
  "10-19": { y: 1901, e: "🗼", t: "Rund um den Eiffelturm", x: "Der brasilianische Luftfahrtpionier Alberto Santos-Dumont umrundete mit seinem Luftschiff den Eiffelturm und kehrte innerhalb von 30 Minuten zum Startplatz zurück. Damit gewann er einen hoch dotierten Preis. Einen Großteil des Geldes verteilte er an seine Mechaniker und an Arme in Paris." },
  "10-20": { e: "🦥", t: "Tag des Faultiers", x: "Heute ist Internationaler Tag des Faultiers. Faultiere bewegen sich so langsam, dass in ihrem Fell Algen wachsen, die sie grünlich tarnen. Sie steigen nur etwa einmal pro Woche vom Baum, um ihr Geschäft zu erledigen. Schwimmen können sie dagegen erstaunlich gut." },
  "10-21": { y: 1879, e: "💡", t: "Die Glühbirne leuchtet", x: "In Menlo Park bei New York brachte Thomas Edisons Team eine Glühbirne mit einem Faden aus verkohltem Baumwollgarn über viele Stunden zum Leuchten. Zuvor hatten sie Tausende Materialien getestet. Die Glühbirne gab es schon vorher, doch Edison machte sie haltbar und alltagstauglich." },
  "10-22": { y: 1811, e: "🎹", t: "Franz Liszt wird geboren", x: "Der im heutigen Burgenland geborene Franz Liszt war der erste Superstar der Musik: Bei seinen Klavierkonzerten fielen Zuhörerinnen in Ohnmacht und stritten sich um seine Handschuhe. Man nannte das Lisztomanie. Er erfand auch das Soloklavierkonzert, bei dem ein Pianist allein einen Abend bestreitet." },
  "10-23": { e: "🧪", t: "Tag des Mols", x: "Heute ist Tag des Mols, gefeiert von Chemikern von 6:02 Uhr morgens bis 6:02 Uhr abends. Der Grund: Die Avogadro-Zahl beträgt rund 6,02 mal 10 hoch 23 – so viele Teilchen enthält ein Mol eines Stoffes. In 18 Gramm Wasser, also einem Schluck, stecken so viele Moleküle." },
  "10-24": { y: 1632, e: "🔬", t: "Antoni van Leeuwenhoek wird geboren", x: "Der niederländische Tuchhändler Antoni van Leeuwenhoek schliff winzige Linsen und baute damit Mikroskope, die bis zu rund 270-fach vergrößerten. Als erster Mensch sah er Bakterien, die er Tierchen nannte, sowie Blutkörperchen. Er gilt als Vater der Mikrobiologie – obwohl er nie studiert hatte." },
  "10-25": { y: 1881, e: "🎨", t: "Pablo Picasso wird geboren", x: "Der spanische Maler Pablo Picasso konnte schon als Kind malen wie ein Erwachsener. Später erfand er mit Georges Braque den Kubismus, bei dem Gegenstände in geometrische Formen zerlegt werden. Er schuf in seinem Leben Zehntausende Werke – Gemälde, Zeichnungen, Keramiken und Skulpturen." },
  "10-26": { y: 1863, e: "⚽", t: "Die Regeln des Fußballs", x: "In einer Londoner Gaststätte gründeten Vertreter mehrerer Klubs die Football Association, den ältesten Fußballverband der Welt. Sie legten gemeinsame Regeln fest, unter anderem, dass der Ball nicht mit den Händen getragen werden darf. Wer das anders wollte, spielte fortan Rugby." },
  "10-27": { y: 1782, e: "🎻", t: "Niccolò Paganini wird geboren", x: "Der italienische Geiger Niccolò Paganini spielte so virtuos, dass man ihm nachsagte, er habe seine Seele dem Teufel verkauft. Er konnte ganze Stücke auf einer einzigen Saite spielen. Heute weiß man, dass er vermutlich besonders bewegliche Finger hatte, was ihm schwierige Griffe erleichterte." },
  "10-28": { y: 1886, e: "🗽", t: "Die Freiheitsstatue", x: "In New York wurde die Freiheitsstatue eingeweiht, ein Geschenk aus Frankreich. Ihre Außenhaut besteht aus Kupferplatten, kaum dicker als zwei Münzen. Das innere Stahlgerüst entwarf Gustave Eiffel, der später den Eiffelturm baute. Ursprünglich glänzte sie kupferrot – die grüne Farbe entstand durch Witterung." },
  "10-29": { y: 1969, e: "💬", t: "Die erste Internetnachricht", x: "Ein Student in Los Angeles versuchte, sich über das neue Netz Arpanet bei einem Computer in Stanford anzumelden, und tippte LOGIN. Nach den ersten beiden Buchstaben L und O stürzte das System ab. So lautete die erste Nachricht des späteren Internets: LO. Eine Stunde später klappte es." },
  "10-30": { y: 1888, e: "🖊️", t: "Der Kugelschreiber wird patentiert", x: "Der Amerikaner John Loud erhielt ein Patent für einen Stift mit einer drehbaren Kugel an der Spitze, mit dem er Leder markieren wollte. Für Papier war er zu grob. Brauchbar wurde der Kugelschreiber erst in den 1930er-Jahren durch den Ungarn László Bíró – in England heißt er deshalb bis heute Biro." },
  "10-31": { e: "🎃", t: "Halloween", x: "Heute ist Halloween. Der Name kommt von All Hallows’ Eve, dem Abend vor Allerheiligen. Der Brauch stammt aus Irland, wo man ursprünglich Rüben aushöhlte. Irische Auswanderer nahmen ihn mit nach Amerika und verwendeten dort Kürbisse. Von dort kehrte er in den 1990er-Jahren nach Europa zurück." },
  "11-01": { e: "🥦", t: "Weltvegantag", x: "Heute ist Weltvegantag. Veganer verzichten auf alle tierischen Produkte, also auch auf Milch, Eier und Honig. Das Wort vegan wurde 1944 in England geprägt. In Deutschland ernährt sich nur ein kleiner Teil der Menschen vegan, doch das Angebot an pflanzlichen Alternativen ist in den letzten Jahren stark gewachsen." },
  "11-02": { y: 2000, e: "🛰️", t: "Die ISS wird bewohnt", x: "Die erste Besatzung zog in die Internationale Raumstation ein: ein Amerikaner und zwei Russen. Seitdem ist die ISS ununterbrochen bewohnt. Sie umkreist die Erde in rund 400 Kilometern Höhe etwa alle 90 Minuten – die Besatzung erlebt also 16 Sonnenaufgänge am Tag." },
  "11-03": { y: 1957, e: "🐕", t: "Laika im All", x: "Mit Sputnik 2 flog die Hündin Laika als erstes Lebewesen in eine Erdumlaufbahn. Sie war eine Straßenhündin aus Moskau, die man für robust hielt. Eine Rückkehr war nicht vorgesehen, und sie starb nach wenigen Stunden an Überhitzung. Ihr Flug zeigte, dass Lebewesen den Start überstehen können." },
  "11-04": { y: 1879, e: "🧾", t: "Die Registrierkasse", x: "Der amerikanische Wirt James Ritty erhielt ein Patent auf eine Registrierkasse. Er wollte verhindern, dass seine Angestellten heimlich Geld aus der Kasse nahmen. Die Idee kam ihm auf einem Dampfschiff, als er ein Zählwerk sah, das die Umdrehungen der Schiffsschraube zählte." },
  "11-05": { e: "🌊", t: "Tag des Tsunamis", x: "Heute ist Welt-Tsunami-Tag. Tsunamis entstehen meist durch Seebeben, die große Wassermassen anheben. Auf offener See sind die Wellen kaum spürbar, doch an der Küste türmen sie sich meterhoch auf. Ein wichtiges Warnzeichen: Wenn sich das Meer plötzlich weit zurückzieht, sollte man sofort ins Hochgelegene fliehen." },
  "11-06": { y: 1814, e: "🎷", t: "Adolphe Sax wird geboren", x: "Der belgische Instrumentenbauer Adolphe Sax erfand das Saxofon, ein Blasinstrument aus Metall, das trotzdem zu den Holzblasinstrumenten zählt, weil der Ton mit einem Rohrblatt erzeugt wird. Als Kind überlebte er zahlreiche Unfälle, etwa einen Sturz, eine Vergiftung und eine Explosion." },
  "11-07": { y: 1867, e: "☢️", t: "Marie Curie wird geboren", x: "Die in Warschau geborene Marie Curie erforschte in Paris die Radioaktivität und entdeckte die Elemente Polonium und Radium. Sie erhielt als erster Mensch zwei Nobelpreise in verschiedenen Naturwissenschaften. Ihre Notizbücher sind bis heute so radioaktiv, dass man sie nur mit Schutzkleidung einsehen darf." },
  "11-08": { y: 1895, e: "🦴", t: "Röntgenstrahlen entdeckt", x: "Wilhelm Conrad Röntgen experimentierte in Würzburg mit einer Glasröhre und bemerkte, dass ein Leuchtschirm im Raum aufleuchtete, obwohl die Röhre abgedeckt war. Er hatte eine unsichtbare Strahlung entdeckt, die er X-Strahlen nannte. Das erste Röntgenbild zeigte die Hand seiner Frau mit ihrem Ehering." },
  "11-09": { y: 1934, e: "🌌", t: "Carl Sagan wird geboren", x: "Der amerikanische Astronom Carl Sagan erklärte Millionen Menschen das Universum, vor allem mit der Fernsehserie „Unser Kosmos“. Er arbeitete an Missionen zu Mars und Jupiter mit und regte die goldene Schallplatte an Bord der Voyager-Sonden an. Von ihm stammt der Satz: Wir sind aus Sternenstaub gemacht." },
  "11-10": { e: "🔬", t: "Welttag der Wissenschaft", x: "Heute ist Welttag der Wissenschaft für Frieden und Entwicklung. Wissenschaft hat unser Leben in den letzten Jahrhunderten grundlegend verändert: Die Lebenserwartung hat sich verdoppelt, Krankheiten wurden besiegt, und wir wissen, wie alt das Universum ist. Der Tag soll zeigen, wie Forschung allen Menschen nützt." },
  "11-11": { e: "🤡", t: "Start der Karnevalssaison", x: "Heute um 11:11 Uhr beginnt in vielen Regionen die Karnevalssaison, die fünfte Jahreszeit. Die Elf gilt als Narrenzahl, weil sie über der Zehn der Gebote steht und zugleich eine Schnapszahl ist. Den Höhepunkt erreicht die Saison an den tollen Tagen vor Aschermittwoch." },
  "11-12": { y: 2014, e: "☄️", t: "Landung auf einem Kometen", x: "Das europäische Landegerät Philae setzte als erstes von Menschen gebautes Objekt auf einem Kometen auf, dem Kometen 67P. Weil seine Harpunen nicht feuerten, prallte es zweimal ab und landete im Schatten einer Felswand. Trotzdem sendete es noch zwei Tage lang Messdaten zur Erde." },
  "11-13": { e: "💛", t: "Tag der Freundlichkeit", x: "Heute ist Welttag der Freundlichkeit. Studien zeigen, dass kleine freundliche Taten nicht nur dem Empfänger guttun, sondern auch dem, der sie ausführt: Wer anderen hilft, ist oft zufriedener. Freundlichkeit ist zudem ansteckend – wer sie erlebt, gibt sie häufiger weiter." },
  "11-14": { y: 1907, e: "🦸‍♀️", t: "Astrid Lindgren wird geboren", x: "Die schwedische Schriftstellerin Astrid Lindgren erfand Pippi Langstrumpf, Michel aus Lönneberga und die Kinder aus Bullerbü. Pippi entstand als Geschichte für ihre kranke Tochter. Lindgrens Bücher wurden in über 100 Sprachen übersetzt. Am selben Tag wurde übrigens 1840 der Maler Claude Monet geboren." },
  "11-15": { y: 1971, e: "🔲", t: "Der erste Mikroprozessor", x: "Die Firma Intel brachte den 4004 auf den Markt, den ersten Mikroprozessor, der alle Rechenfunktionen auf einem einzigen Chip vereinte. Er war ursprünglich für einen japanischen Tischrechner entwickelt worden und hatte rund 2.300 Transistoren. Heutige Chips enthalten viele Milliarden." },
  "11-16": { y: 1974, e: "📡", t: "Eine Botschaft an Außerirdische", x: "Vom Radioteleskop Arecibo in Puerto Rico wurde eine Funkbotschaft zu einem Sternhaufen in rund 25.000 Lichtjahren Entfernung geschickt. Sie enthielt in Bildpunkten unter anderem die Zahlen eins bis zehn, eine DNA-Doppelhelix und die Umrisse eines Menschen. Eine Antwort wäre frühestens in 50.000 Jahren zu erwarten." },
  "11-17": { e: "👶", t: "Welt-Frühgeborenen-Tag", x: "Heute ist Welt-Frühgeborenen-Tag. Etwa jedes zehnte Baby weltweit kommt zu früh zur Welt, also vor der 37. Schwangerschaftswoche. Dank moderner Medizin überleben heute selbst Kinder, die weniger als 500 Gramm wiegen. Wichtig ist auch viel Hautkontakt mit den Eltern, das sogenannte Känguruhen." },
  "11-18": { y: 1928, e: "🐭", t: "Micky Maus hat Premiere", x: "In New York lief der Zeichentrickfilm „Steamboat Willie“ an, in dem Micky Maus pfeifend ein Dampfschiff steuert. Es war einer der ersten Zeichentrickfilme mit Ton, der genau zum Bild passte. Walt Disney sprach Micky anfangs selbst. Der Tag gilt als Mickys Geburtstag." },
  "11-19": { e: "🚽", t: "Welttoilettentag", x: "Heute ist Welttoilettentag – ein ernstes Thema. Rund 3,5 Milliarden Menschen haben keinen Zugang zu einer sicheren Toilette. Die Folgen sind verschmutztes Wasser und Krankheiten wie Durchfall, an denen jedes Jahr viele Kinder sterben. Moderne Abwassersysteme haben Städte gesünder gemacht als fast jede andere Erfindung." },
  "11-20": { y: 1889, e: "🌌", t: "Edwin Hubble wird geboren", x: "Der amerikanische Astronom Edwin Hubble wies nach, dass viele Nebelflecken am Himmel eigene Galaxien weit außerhalb der Milchstraße sind. Außerdem entdeckte er, dass sich die Galaxien voneinander entfernen: Das Universum dehnt sich aus. Nach ihm wurde das berühmte Weltraumteleskop benannt." },
  "11-21": { e: "👋", t: "Welthallotag", x: "Heute ist Welthallotag. Die Idee: Man soll an diesem Tag mindestens zehn Menschen grüßen, um zu zeigen, dass Gespräche Konflikte lösen können. Das Wort Hallo stammt vermutlich von einem alten Ruf, mit dem man einen Fährmann über den Fluss herbeirief." },
  "11-22": { y: 1995, e: "🤠", t: "Toy Story kommt ins Kino", x: "In den USA lief „Toy Story“ an, der erste abendfüllende Kinofilm, der vollständig am Computer animiert wurde. Die Geschichte des Cowboys Woody und des Astronauten Buzz Lightyear begeisterte Kinder und Erwachsene. Für manche Einzelbilder brauchten die Computer damals viele Stunden Rechenzeit." },
  "11-23": { e: "🐚", t: "Fibonacci-Tag", x: "Heute ist Fibonacci-Tag, weil das Datum in amerikanischer Schreibweise 11/23 lautet – der Anfang der Fibonacci-Folge 1, 1, 2, 3. In dieser Folge ist jede Zahl die Summe der beiden vorherigen. Sie taucht erstaunlich oft in der Natur auf, etwa in der Anordnung von Sonnenblumenkernen und Tannenzapfenschuppen." },
  "11-24": { y: 1859, e: "📗", t: "Die Entstehung der Arten erscheint", x: "Charles Darwins Buch „Über die Entstehung der Arten“ kam in die Buchläden. Die erste Auflage von rund 1.250 Exemplaren war schnell vergriffen. Darwin erklärte darin, wie sich Arten durch natürliche Auslese über lange Zeiträume verändern. Das Buch veränderte die Biologie grundlegend." },
  "11-25": { y: 1844, e: "🚗", t: "Carl Benz wird geboren", x: "In Karlsruhe kam Carl Benz zur Welt, der 1886 das erste Automobil mit Benzinmotor zum Patent anmeldete. Sein Vater, ein Lokführer, war früh gestorben. Seine Mutter ermöglichte ihm trotz Armut ein Studium. Die Firma Benz fusionierte später mit Daimler zu Daimler-Benz." },
  "11-26": { y: 1922, e: "🏺", t: "Wunderbare Dinge", x: "Der Archäologe Howard Carter blickte in Ägypten im Kerzenschein durch ein Loch in eine versiegelte Grabkammer. Auf die Frage, ob er etwas sehe, soll er geantwortet haben: Ja, wunderbare Dinge. Es war das fast unberührte Grab des Pharaos Tutanchamun mit über 5.000 Beigaben." },
  "11-27": { y: 1701, e: "🌡️", t: "Anders Celsius wird geboren", x: "Der schwedische Astronom Anders Celsius schlug eine Temperaturskala mit 100 Stufen zwischen Gefrier- und Siedepunkt des Wassers vor. Ursprünglich lag bei ihm der Siedepunkt bei 0 und der Gefrierpunkt bei 100 Grad. Erst nach seinem Tod wurde die Skala umgedreht." },
  "11-28": { y: 1964, e: "🔴", t: "Mariner 4 fliegt zum Mars", x: "Die Raumsonde Mariner 4 startete zum Mars und lieferte im folgenden Sommer die ersten Nahaufnahmen eines anderen Planeten. Die 21 Bilder zeigten eine kraterübersäte, öde Oberfläche – eine Enttäuschung für alle, die auf Marskanäle und Leben gehofft hatten. Die Übertragung eines Bildes dauerte Stunden." },
  "11-29": { y: 1898, e: "🦁", t: "C. S. Lewis wird geboren", x: "Der irische Schriftsteller Clive Staples Lewis schrieb die „Chroniken von Narnia“, in denen Kinder durch einen Kleiderschrank in eine magische Welt gelangen, in der der Löwe Aslan herrscht. Er war eng befreundet mit J. R. R. Tolkien, dem Autor des „Herrn der Ringe“; beide lasen sich ihre Texte gegenseitig vor." },
  "11-30": { y: 2022, e: "🤖", t: "ChatGPT wird veröffentlicht", x: "Das Unternehmen OpenAI stellte den Chatbot ChatGPT kostenlos ins Netz. Innerhalb von fünf Tagen hatte er eine Million Nutzer. Das Sprachmodell kann Fragen beantworten, Texte schreiben und Programme erklären, macht aber auch Fehler. Die Veröffentlichung löste einen weltweiten Boom der künstlichen Intelligenz aus." },
  "12-01": { e: "❄️", t: "Meteorologischer Winteranfang", x: "Heute beginnt für Wetterdienste der Winter. Die Tage sind nun besonders kurz: In Hamburg geht die Sonne erst gegen halb neun auf und schon vor vier wieder unter. Viele Tiere halten Winterschlaf oder Winterruhe, andere wie Eichhörnchen zehren von ihren im Herbst versteckten Vorräten." },
  "12-02": { y: 1859, e: "🔵", t: "Georges Seurat wird geboren", x: "Der französische Maler Georges Seurat setzte seine Bilder aus Tausenden kleinen Farbpunkten zusammen. Erst aus der Entfernung verschmelzen sie im Auge zu Flächen und Farben. Diese Technik heißt Pointillismus. Für sein berühmtestes Bild, einen Sonntagnachmittag auf einer Seine-Insel, brauchte er rund zwei Jahre." },
  "12-03": { y: 1992, e: "💬", t: "Die erste SMS", x: "Ein britischer Ingenieur schickte von einem Computer die erste SMS an ein Mobiltelefon. Sie lautete: Merry Christmas. Antworten konnte der Empfänger nicht, denn Handys konnten damals noch keine Nachrichten schreiben. Die Länge einer SMS wurde auf 160 Zeichen begrenzt." },
  "12-04": { e: "🌸", t: "Barbaratag", x: "Heute ist Barbaratag. Nach altem Brauch schneidet man Zweige von Kirsch- oder Apfelbäumen und stellt sie in einer warmen Stube ins Wasser. Mit etwas Glück blühen sie an Weihnachten. Das gelingt, wenn die Zweige vorher schon einen Frost erlebt haben – er signalisiert ihnen, dass der Winter vorbei sein könnte." },
  "12-05": { e: "🪱", t: "Weltbodentag", x: "Heute ist Weltbodentag. In einer Handvoll gesunder Erde leben mehr Lebewesen, als es Menschen auf der Erde gibt: Bakterien, Pilze, Würmer und Insekten. Es dauert oft Hunderte Jahre, bis sich wenige Zentimeter fruchtbarer Boden bilden – doch durch Erosion und Versiegelung geht er schnell verloren." },
  "12-06": { e: "🎅", t: "Nikolaustag", x: "Heute ist Nikolaustag. Der Brauch geht auf den heiligen Nikolaus von Myra zurück, einen Bischof, der im 4. Jahrhundert in der heutigen Türkei lebte und der Legende nach heimlich Gaben an Arme verteilte. Deshalb stellen Kinder am Vorabend Stiefel oder Schuhe vor die Tür." },
  "12-07": { y: 1972, e: "🌍", t: "Die blaue Murmel", x: "Die Besatzung von Apollo 17 fotografierte auf dem Weg zum Mond die vollständig beleuchtete Erde. Das Bild „Blue Marble“ zeigt Afrika, die Arabische Halbinsel und die Antarktis unter weißen Wolken. Es gehört zu den meistverbreiteten Fotos der Welt. Apollo 17 war die bisher letzte bemannte Mondlandung." },
  "12-08": { y: 1865, e: "🌲", t: "Jean Sibelius wird geboren", x: "Der finnische Komponist Jean Sibelius ließ sich von den Wäldern, Seen und Sagen seiner Heimat inspirieren. Sein Werk „Finlandia“ wurde zu einer Art zweiter Nationalhymne Finnlands. Er liebte die Natur so sehr, dass er Vögel am Himmel beobachtete und ihre Rufe in seine Musik einfließen ließ." },
  "12-09": { y: 1968, e: "🖱️", t: "Die Mutter aller Präsentationen", x: "Der Ingenieur Douglas Engelbart führte in San Francisco vor einem staunenden Publikum Dinge vor, die erst Jahrzehnte später alltäglich wurden: eine Computermaus, Textbearbeitung am Bildschirm, Links zwischen Dokumenten und eine Videokonferenz. Die Vorführung ging als Mutter aller Demos in die Geschichte der Technik ein." },
  "12-10": { e: "🏅", t: "Nobelpreisverleihung", x: "Heute werden in Stockholm und Oslo die Nobelpreise verliehen, am Todestag von Alfred Nobel, dem Erfinder des Dynamits. Er bestimmte in seinem Testament, dass sein Vermögen jene auszeichnen solle, die der Menschheit den größten Nutzen gebracht haben. Am 10. Dezember wurde übrigens auch Ada Lovelace geboren, die erste Programmiererin." },
  "12-11": { e: "⛰️", t: "Tag der Berge", x: "Heute ist Internationaler Tag der Berge. Berge bedecken rund ein Viertel der Landfläche der Erde und liefern einem großen Teil der Menschheit Süßwasser, das in Gletschern und Schnee gespeichert ist. Der höchste Berg Deutschlands ist die Zugspitze mit knapp 3.000 Metern. An diesem Tag wurde 1843 außerdem Robert Koch geboren." },
  "12-12": { y: 1901, e: "📡", t: "Funk über den Atlantik", x: "Guglielmo Marconi empfing an der Küste Neufundlands mit einer an einem Drachen befestigten Antenne ein Funksignal aus England: dreimal kurz, den Morsebuchstaben S. Viele Experten hatten behauptet, die Erdkrümmung mache das unmöglich. Tatsächlich werden Funkwellen von einer Luftschicht in großer Höhe zurückgeworfen." },
  "12-13": { e: "🕯️", t: "Luciatag", x: "Heute wird in Schweden und anderen nordischen Ländern der Luciatag gefeiert, eines der wichtigsten Lichterfeste in der dunkelsten Jahreszeit. Mädchen in weißen Gewändern tragen einen Kranz mit Kerzen auf dem Kopf und singen. Dazu gibt es Safranbrötchen. Früher galt der 13. Dezember als längste Nacht des Jahres." },
  "12-14": { e: "🌠", t: "Die Geminiden", x: "Um den 14. Dezember erreichen die Geminiden ihren Höhepunkt, einer der ergiebigsten Sternschnuppenströme des Jahres. Anders als die meisten Ströme stammen sie nicht von einem Kometen, sondern vom Asteroiden Phaethon. In klaren, dunklen Nächten kann man manchmal über hundert Sternschnuppen pro Stunde sehen." },
  "12-15": { y: 1832, e: "🗼", t: "Gustave Eiffel wird geboren", x: "Der französische Ingenieur Gustave Eiffel war ein Meister des Eisenbaus. Er errichtete Brücken und Bahnhöfe in aller Welt, das innere Gerüst der Freiheitsstatue und den Eiffelturm. Den Turm nutzte er selbst für wissenschaftliche Versuche zu Wetter, Funk und Luftwiderstand." },
  "12-16": { y: 1770, e: "🎹", t: "Ludwig van Beethoven wird geboren", x: "In Bonn kam Ludwig van Beethoven zur Welt – vermutlich an diesem Tag, getauft wurde er am 17. Dezember. Obwohl er im Laufe seines Lebens fast völlig ertaubte, komponierte er weiter, darunter die Neunte Sinfonie mit der „Ode an die Freude“. Bei der Uraufführung musste man ihn umdrehen, damit er den Jubel sah." },
  "12-17": { y: 1903, e: "✈️", t: "Der erste Motorflug", x: "Bei Kitty Hawk in North Carolina hob Orville Wright mit dem Flyer ab, einem motorisierten Flugzeug, das er mit seinem Bruder Wilbur gebaut hatte. Der erste Flug dauerte zwölf Sekunden und reichte rund 37 Meter weit. Am selben Tag gelang ein Flug über fast 260 Meter." },
  "12-18": { y: 1879, e: "🐟", t: "Paul Klee wird geboren", x: "Der Maler Paul Klee wurde bei Bern geboren und lehrte später am Bauhaus. Seine Bilder aus farbigen Feldern, Linien und Zeichen wirken oft wie Musik oder Kinderzeichnungen – er war selbst ein begabter Geiger. Von ihm stammt der Satz: Kunst gibt nicht das Sichtbare wieder, sondern macht sichtbar." },
  "12-19": { y: 1843, e: "👻", t: "Eine Weihnachtsgeschichte erscheint", x: "Charles Dickens’ „Eine Weihnachtsgeschichte“ kam in die Läden: Der geizige Ebenezer Scrooge wird in einer Nacht von drei Geistern besucht und wandelt sich zum großzügigen Menschen. Die erste Auflage war bis Heiligabend ausverkauft. Das Buch prägte das Bild vom Weihnachtsfest als Fest der Familie und Nächstenliebe." },
  "12-20": { y: 1951, e: "💡", t: "Strom aus Kernenergie", x: "Im Versuchsreaktor EBR-I in Idaho wurde zum ersten Mal Strom aus Kernenergie erzeugt. Er reichte zunächst gerade für vier Glühbirnen. Am nächsten Tag versorgte der Reaktor das ganze Gebäude mit Strom. Die Wissenschaftler schrieben ihre Namen mit Kreide an die Wand, wo sie bis heute zu sehen sind." },
  "12-21": { e: "🌘", t: "Winteranfang", x: "Um den 21. Dezember ist Wintersonnenwende: Die Sonne steht mittags so tief wie im ganzen Jahr nicht, und es ist der kürzeste Tag. Von nun an werden die Tage wieder länger. Viele alte Lichterfeste rund um diese Zeit feiern die Wiederkehr der Sonne. Nördlich des Polarkreises herrscht Polarnacht." },
  "12-22": { y: 1858, e: "🎭", t: "Giacomo Puccini wird geboren", x: "Der italienische Komponist Giacomo Puccini schrieb einige der beliebtesten Opern überhaupt, darunter „La Bohème“, „Tosca“ und „Madama Butterfly“. Seine Melodien sind so eingängig, dass sie oft in Filmen und Werbung zu hören sind. Er war zudem ein begeisterter Autofahrer und Jäger." },
  "12-23": { y: 1947, e: "📻", t: "Der Transistor wird vorgeführt", x: "In den Bell Laboratories in New Jersey führten die Physiker John Bardeen, Walter Brattain und William Shockley ihren Kollegen den ersten Transistor vor, einen winzigen elektronischen Schalter und Verstärker. Er ersetzte die großen Röhren und machte Radios, Computer und Smartphones möglich. Die drei erhielten dafür den Nobelpreis." },
  "12-24": { y: 1968, e: "🌍", t: "Erdaufgang", x: "An Heiligabend umkreisten die Astronauten von Apollo 8 als erste Menschen den Mond. Dabei sahen sie die Erde über dem Mondhorizont aufgehen, und William Anders fotografierte den Anblick. Das Bild „Earthrise“ zeigte, wie klein und verletzlich unser Planet ist, und inspirierte die Umweltbewegung." },
  "12-25": { y: 2021, e: "🔭", t: "Das Webb-Teleskop startet", x: "Am ersten Weihnachtstag startete das James-Webb-Weltraumteleskop mit einer Ariane-Rakete von Französisch-Guayana ins All. Sein riesiger goldbeschichteter Spiegel musste sich im All entfalten wie ein Origami. Es ist rund 1,5 Millionen Kilometer von der Erde entfernt und blickt tief in die Vergangenheit des Universums." },
  "12-26": { y: 1898, e: "☢️", t: "Radium wird bekannt gegeben", x: "Marie und Pierre Curie berichteten der Pariser Akademie der Wissenschaften von einem neuen, stark strahlenden Element, das sie Radium nannten. Um wenige Zehntelgramm zu gewinnen, mussten sie Tonnen von Erz verarbeiten. Radium leuchtet im Dunkeln und wurde anfangs bedenkenlos für Leuchtziffern verwendet." },
  "12-27": { y: 1822, e: "🧫", t: "Louis Pasteur wird geboren", x: "Der französische Chemiker Louis Pasteur bewies, dass Mikroben Gärung und Krankheiten verursachen. Er entwickelte Impfstoffe gegen Tollwut und Milzbrand und das Pasteurisieren, bei dem Milch kurz erhitzt wird, um Keime abzutöten. Am selben Tag wurde 1571 der Astronom Johannes Kepler geboren." },
  "12-28": { y: 1895, e: "🎞️", t: "Die erste Kinovorführung", x: "In einem Pariser Café zeigten die Brüder Auguste und Louis Lumière erstmals gegen Eintritt Filme auf einer Leinwand. Zu sehen waren kurze Szenen wie Arbeiter, die eine Fabrik verlassen. Einer späteren Legende nach sollen Zuschauer vor einem heranfahrenden Zug erschrocken zurückgewichen sein." },
  "12-29": { y: 1800, e: "🛞", t: "Charles Goodyear wird geboren", x: "Der Amerikaner Charles Goodyear suchte jahrelang nach einem Weg, Gummi haltbar zu machen, denn Naturkautschuk wurde in der Hitze klebrig und in der Kälte brüchig. Der Legende nach ließ er eine Mischung aus Gummi und Schwefel versehentlich auf einen heißen Ofen fallen – und erfand so die Vulkanisation." },
  "12-30": { y: 1865, e: "🐻", t: "Rudyard Kipling wird geboren", x: "Der im indischen Bombay geborene Schriftsteller Rudyard Kipling schrieb „Das Dschungelbuch“ über den Jungen Mowgli, der von Wölfen aufgezogen wird und vom Bären Balu und dem Panther Baghira lernt. 1907 erhielt Kipling als erster englischsprachiger Autor den Literaturnobelpreis." },
  "12-31": { e: "🎆", t: "Silvester", x: "Heute ist Silvester, benannt nach Papst Silvester I., dessen Gedenktag auf den letzten Tag des Jahres fällt. Mit Feuerwerk und Lärm sollten früher böse Geister vertrieben werden. Zu den Bräuchen gehören Bleigießen, heute meist mit Wachs, und in vielen Haushalten der Sketch „Dinner for One“." }
};
